	"github.com/regutierrez/hseh/internal/herdr"
	"github.com/regutierrez/hseh/internal/space"
	"github.com/regutierrez/hseh/internal/termtext"
	"github.com/regutierrez/hseh/internal/trace"
)

// DefaultSnapshotPollMilliseconds is the live membership/status refresh interval.
// It is slower than the preview clock: membership changes rarely, terminal output often.
const DefaultSnapshotPollMilliseconds = 1000

// DefaultGitPollMilliseconds is the workspace git branch/status refresh interval.
const DefaultGitPollMilliseconds = 3000

// DefaultPreviewLoadingDelay is how long a new preview may take before "Loading preview…" replaces the last frame.
const DefaultPreviewLoadingDelay = 500 * time.Millisecond

type bootMsg struct{}

// previewLoadedMsg carries one finished read: a live pane (paneID) or a directory listing (dir).
type previewLoadedMsg struct {
	seq      uint64
	targetID string
	paneID   string
	dir      string
	text     string
	err      error
}

// previewLoadingMsg fires when a selection-change preview is still in flight after the loading delay.
type previewLoadingMsg struct{ seq uint64 }

// previewTickMsg re-reads the selected live pane once the previous read finished.
type previewTickMsg struct{ seq uint64 }

type snapshotTickMsg struct{}

type gitTickMsg struct{}

type snapshotLoadedMsg struct {
	seq        uint64
	snapshot   herdr.SessionSnapshot
	history    focus.History
	records    []space.AssociationRecord
	unresolved []space.AssociationRecord
	liveErr    error
	catalogErr error
}

// catalogLoadedMsg carries the sidebar layout and reusable-space definitions loaded after first paint.
type catalogLoadedMsg struct {
	layout      SidebarLayout
	definitions []space.Definition
	errs        []string
}

type acceptedMsg struct{}

type errorMsg struct{ err error }

type cancelSet struct {
	mu       sync.Mutex
	preview  context.CancelFunc
	snapshot context.CancelFunc
	accept   context.CancelFunc
	git      context.CancelFunc
	catalog  context.CancelFunc
}

func (c *cancelSet) replace(slot *context.CancelFunc) context.Context {
	if c == nil {
		return context.Background()
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if *slot != nil {
		(*slot)()
	}
	ctx, cancel := context.WithCancel(context.Background())
	*slot = cancel
	return ctx
}

func (c *cancelSet) cancelPreview() {
	if c == nil {
		return
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.preview != nil {
		c.preview()
		c.preview = nil
	}
}

func (c *cancelSet) cancelAll() {
	if c == nil {
		return
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	for _, slot := range []*context.CancelFunc{&c.preview, &c.snapshot, &c.accept, &c.git, &c.catalog} {
		if *slot != nil {
			(*slot)()
			*slot = nil
		}
	}
}

func (m *model) io() *cancelSet {
	if m.cancels == nil {
		m.cancels = &cancelSet{}
	}
	return m.cancels
}

type model struct {
	view               string
	query              string
	allItems           []Item
	visible            []Item
	searchScratch      []string
	selectedID         string
	snapshot           herdr.SessionSnapshot
	history            focus.History
	layout             SidebarLayout
	definitions        []space.Definition
	associationRecords []space.AssociationRecord
	unresolvedRecords  []space.AssociationRecord
	catalogErrors      []string
	width              int
	height             int
	theme              colorTheme

	// Preview state. previewText is the last frame shown; it survives selection
	// changes until the new read lands so navigation never blanks the pane.
	previewText         string
	previewTextLive     bool
	previewListing      bool
	previewErr          string
	previewPane         string
	previewDir          string
	previewLoading      bool
	previewInFlight     bool
	previewSeq          uint64
	previewEvery        time.Duration
	previewLoadingDelay time.Duration
	readPane            func(ctx context.Context, paneID string) (string, error)
	readDir             func(ctx context.Context, dir string) (string, error)

	// Catalog state. snapshotReady flips on the first live snapshot; catalogReady
	// on the first layout/definition load. Until then the list shows loading copy.
	snapshotReady    bool
	catalogReady     bool
	liveErr          string
	assocErr         string
	acceptErr        string
	statusErr        string
	snapshotEvery    time.Duration
	gitEvery         time.Duration
	snapshotSeq      uint64
	snapshotInFlight bool
	gitInFlight      bool
	gitByDirectory   map[string]gitinfo.WorkspaceGit

	widePreviewMinCols int
	splitListWidth     int
	dividerDrag        bool
	mouseOut           io.Writer

	launch        LaunchContext
	pendingAccept bool
	quitting      bool
	cancels       *cancelSet
	milestones    map[string]bool
}

// newModel builds a model with the catalog already loaded (used by tests and list tooling).
func newModel(view string, snapshot herdr.SessionSnapshot, history focus.History, layout SidebarLayout, pollEvery time.Duration, wideMin int) model {
	history = focus.Prune(history, snapshot)
	launch := launchFromEnv(snapshot, history)
	m := model{
		view:               view,
		snapshot:           snapshot,
		history:            history,
		layout:             layout,
		previewEvery:       pollEvery,
		widePreviewMinCols: wideMin,
		launch:             launch,
		cancels:            &cancelSet{},
		snapshotReady:      true,
		catalogReady:       true,
	}
	m.rebuildVisible()
	return m
}

// newAsyncModel paints chrome first; snapshot, history, layout and definitions load after Init.
func newAsyncModel(view string, theme colorTheme, pollEvery time.Duration, wideMin int, configErrs []string) model {
	m := model{
		view:               view,
		theme:              theme,
		layout:             defaultSidebarLayout(),
		previewEvery:       pollEvery,
		widePreviewMinCols: wideMin,
		catalogErrors:      configErrs,
		cancels:            &cancelSet{},
	}
	m.recomputeStatus()
	return m
}

func (m *model) setSpaceCatalog(definitions []space.Definition, records, unresolved []space.AssociationRecord, errs []string) {
	m.definitions = definitions
	m.associationRecords = records
	m.unresolvedRecords = unresolved
	m.catalogErrors = errs
	m.catalogReady = true
	m.recomputeStatus()
	m.rebuildVisible()
}

// recomputeStatus picks the footer error: a failed accept, then live socket, then association, then config.
func (m *model) recomputeStatus() {
	switch {
	case m.acceptErr != "":
		m.statusErr = m.acceptErr
	case m.liveErr != "":
		m.statusErr = m.liveErr
	case m.assocErr != "":
		m.statusErr = m.assocErr
	case len(m.catalogErrors) > 0:
		m.statusErr = strings.Join(m.catalogErrors, "; ")
	default:
		m.statusErr = ""
	}
}

func (m *model) rebuildVisible() {
	items := m.catalogItems()
	m.allItems = items
	m.visible, m.searchScratch = filterItemsInto(m.visible[:0], m.searchScratch, items, m.query)
	m.selectedID = PreselectItemID(m.view, m.visible, m.history, m.launch)
	// previewPane and previewDir stay unset here so the first afterSelectionChange
	// treats the preselected item as a selection change: a hedged read with the
	// loading indicator, not an unhedged refresh that can sit on Herdr's 100ms tick.
}

func (m *model) catalogItems() []Item {
	snapshot := m.snapshot
	snapshot.GitByDirectory = m.gitByDirectory
	items := BuildItemsWithLayout(m.view, snapshot, m.history, m.layout)
	return AppendUnopenedDefinitionItems(items, m.view, snapshot, m.definitions, m.associationRecords, m.unresolvedRecords)
}

// previewTarget names what the item previews: a live agent pane, or the directory of a space/template.
func previewTarget(item Item) (paneID, dir string) {
	if item.Kind == KindAgent {
		return item.PreviewPane, ""
	}
	return "", item.Path
}

func (m model) previewTargetMatches(item Item) bool {
	paneID, dir := previewTarget(item)
	return paneID == m.previewPane && dir == m.previewDir
}

func (m model) Init() tea.Cmd {
	return func() tea.Msg { return bootMsg{} }
}

func tickAfter(every, fallback time.Duration, msg tea.Msg) tea.Cmd {
	if every <= 0 {
		every = fallback
	}
	return tea.Tick(every, func(time.Time) tea.Msg { return msg })
}

func (m model) tickSnapshot() tea.Cmd {
	return tickAfter(m.snapshotEvery, time.Duration(DefaultSnapshotPollMilliseconds)*time.Millisecond, snapshotTickMsg{})
}

func (m model) tickGit() tea.Cmd {
	return tickAfter(m.gitEvery, time.Duration(DefaultGitPollMilliseconds)*time.Millisecond, gitTickMsg{})
}

func (m model) tickPreview(seq uint64) tea.Cmd {
	return tickAfter(m.previewEvery, time.Duration(config.DefaultPreviewPollMilliseconds)*time.Millisecond, previewTickMsg{seq: seq})
}

// wideEnoughForPreview reports side-by-side layout. Narrower popups stack the preview instead of hiding it.
func (m model) wideEnoughForPreview() bool {
	return m.frame().mode == previewSide
}

// showsPreview reports whether any preview pane (side or stacked) is on screen.
func (m model) showsPreview() bool {
	return m.frame().mode != previewHidden
}

func (m model) selectedItem() (Item, bool) {
	if m.selectedID == "" {
		return Item{}, false
	}
	for _, item := range m.visible {
		if item.ID == m.selectedID {
			return item, true
		}
	}
	return Item{}, false
}

func (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	if !trace.Enabled() {
		return m, update(&m, msg)
	}
	span := trace.Span("update", "msg", fmt.Sprintf("%T", msg))
	cmd := update(&m, msg)
	span()
	return m, cmd
}

// traceMilestone logs the first occurrence of a named startup milestone.
func (m *model) traceMilestone(name string) {
	if m.milestones == nil {
		m.milestones = map[string]bool{}
	}
	if m.milestones[name] {
		return
	}
	m.milestones[name] = true
	trace.Event("milestone."+name, "items", len(m.visible))
}

func update(m *model, msg tea.Msg) tea.Cmd {
	switch msg := msg.(type) {
	case bootMsg:
		if m.quitting {
			return nil
		}
		var cmds []tea.Cmd
		if !m.catalogReady {
			cmds = append(cmds, m.startCatalog())
		}
		cmds = append(cmds, m.startSnapshot(), m.tickSnapshot(), m.tickGit())
		if m.snapshotReady {
			cmds = append(cmds, m.startGit(), m.afterSelectionChange())
		}
		return tea.Batch(cmds...)
	case tea.WindowSizeMsg:
		wasShown := m.showsPreview()
		m.width = msg.Width
		m.height = msg.Height
		m.traceMilestone("window_size")
		nowShown := m.showsPreview()
		if !nowShown {
			// Keep the last frame for an instant repaint when the popup grows again.
			m.stopPreviewChain()
			return nil
		}
		if !wasShown {
			return m.startPreview(false)
		}
		return nil
	case snapshotTickMsg:
		if m.quitting {
			return nil
		}
		return tea.Batch(m.tickSnapshot(), m.startSnapshot())
	case gitTickMsg:
		if m.quitting {
			return nil
		}
		return tea.Batch(m.tickGit(), m.startGit())
	case previewTickMsg:
		if m.quitting || msg.seq != m.previewSeq || m.previewInFlight {
			return nil
		}
		return m.startPreview(true)
	case previewLoadingMsg:
		if msg.seq == m.previewSeq && m.previewInFlight {
			m.previewLoading = true
		}
		return nil
	case catalogLoadedMsg:
		if m.quitting {
			return nil
		}
		m.layout = msg.layout
		m.definitions = msg.definitions
		m.catalogErrors = append(append([]string{}, m.catalogErrors...), msg.errs...)
		m.catalogReady = true
		m.traceMilestone("catalog_loaded")
		m.recomputeStatus()
		if m.snapshotReady {
			// Template directories need their own git pass; a pass already running picks them up on the next tick.
			return tea.Batch(m.refreshMembership(), m.startGit())
		}
		return nil
	case gitLoadedMsg:
		m.gitInFlight = false
		if m.quitting {
			return nil
		}
		m.gitByDirectory = msg.byDirectory
		if !m.snapshotReady {
			return nil
		}
		return m.refreshMembership()
	case snapshotLoadedMsg:
		if m.quitting || msg.seq != m.snapshotSeq {
			return nil
		}
		m.snapshotInFlight = false
		if msg.liveErr != nil {
			m.liveErr = msg.liveErr.Error()
			m.recomputeStatus()
			return nil
		}
		m.liveErr = ""
		m.snapshot = msg.snapshot
		m.history = msg.history
		if msg.catalogErr != nil {
			m.associationRecords = nil
			m.unresolvedRecords = nil
			m.assocErr = msg.catalogErr.Error()
		} else {
			m.associationRecords = msg.records
			m.unresolvedRecords = msg.unresolved
			m.assocErr = ""
		}
		m.recomputeStatus()
		if !m.snapshotReady {
			m.snapshotReady = true
			m.launch = launchFromEnv(m.snapshot, m.history)
			m.rebuildVisible()
			m.traceMilestone("snapshot_applied")
			return tea.Batch(m.afterSelectionChange(), m.startGit())
		}
		return m.refreshMembership()
	case previewLoadedMsg:
		if msg.seq != m.previewSeq {
			trace.Event("preview.stale", "pane", msg.paneID)
			return nil
		}
		m.previewInFlight = false
		m.previewLoading = false
		if m.quitting {
			return nil
		}
		item, ok := m.selectedItem()
		if !ok || msg.targetID != m.selectedID || !m.showsPreview() {
			return nil
		}
		if paneID, dir := previewTarget(item); msg.paneID != paneID || msg.dir != dir {
			return nil
		}
		if msg.err != nil {
			m.previewErr = msg.err.Error()
			m.previewText = ""
			m.previewTextLive = false
			m.previewListing = false
		} else {
			m.previewErr = ""
			m.previewText = msg.text
			m.previewTextLive = msg.dir == ""
			m.previewListing = msg.dir != ""
			m.traceMilestone("preview_painted")
		}
		if msg.dir != "" {
			// Directory listings are read once per selection; only live panes poll.
			return nil
		}
		return m.tickPreview(m.previewSeq)
	case acceptedMsg:
		m.quitting = true
		m.io().cancelAll()
		return tea.Quit
	case errorMsg:
		m.pendingAccept = false
		m.acceptErr = msg.err.Error()
		m.recomputeStatus()
		return nil
	case tea.KeyMsg:
		switch msg.Type {
		case tea.KeyCtrlC, tea.KeyEsc:
			m.quitting = true
			m.pendingAccept = false
			m.io().cancelAll()
			m.previewSeq++
			m.snapshotSeq++
			return tea.Quit
		case tea.KeyEnter:
			return m.startAccept()
		case tea.KeyUp:
			// Ranked blocks grow upward, so later indexes sit physically higher.
			m.moveSelection(1)
			return m.afterSelectionChange()
		case tea.KeyDown:
			m.moveSelection(-1)
			return m.afterSelectionChange()
		case tea.KeyTab:
			m.cycleView(1)
			return m.afterSelectionChange()
		case tea.KeyShiftTab:
			m.cycleView(-1)
			return m.afterSelectionChange()
		case tea.KeyBackspace:
			if len(m.query) > 0 {
				r := []rune(m.query)
				m.query = string(r[:len(r)-1])
				m.applyQuery()
			}
			return m.afterSelectionChange()
		default:
			if msg.Type == tea.KeyRunes {
				m.query += termtext.StripControls(string(msg.Runes))
				m.applyQuery()
				return m.afterSelectionChange()
			}
		}
	case tea.MouseMsg:
		return m.handleMouse(msg)
	}
	return nil
}

func (m *model) handleMouse(msg tea.MouseMsg) tea.Cmd {
	fr := m.frame()
	if m.dividerDrag {
		switch msg.Action {
		case tea.MouseActionMotion, tea.MouseActionPress:
			if msg.Button == tea.MouseButtonLeft || msg.Button == tea.MouseButtonNone {
				m.setSplitFromMouse(msg.X)
				return nil
			}
			m.dividerDrag = false
			return m.setMouseCellMotion(false)
		default:
			m.dividerDrag = false
			return m.setMouseCellMotion(false)
		}
	}
	if msg.Action != tea.MouseActionPress || msg.Button != tea.MouseButtonLeft {
		return nil
	}
	if fr.mode == previewSide && msg.X == fr.dividerX && msg.Y >= fr.previewY && msg.Y < fr.previewY+fr.previewH {
		m.dividerDrag = true
		return m.setMouseCellMotion(true)
	}
	id := m.itemIDAtMouse(msg.X, msg.Y)
	if id == "" || id == m.selectedID {
		return nil
	}
	m.selectedID = id
	return m.afterSelectionChange()
}

func (m *model) setSplitFromMouse(x int) {
	lo, hi := m.splitListBounds()
	if hi < lo {
		return
	}
	if x < lo {
		x = lo
	}
	if x > hi {
		x = hi
	}
	m.splitListWidth = x
}

// setMouseCellMotion toggles button-motion mouse reporting (DECSET 1002) around a divider drag.
// Ordinary use keeps click-only reporting, enabled by Run.
func (m *model) setMouseCellMotion(on bool) tea.Cmd {
	out := m.mouseOut
	if out == nil {
		return nil
	}
	seq := "\x1b[?1002l"
	if on {
		seq = "\x1b[?1002h"
	}
	return func() tea.Msg {
		_, _ = io.WriteString(out, seq)
		return nil
	}
}

func (m *model) startCatalog() tea.Cmd {
	if m.quitting {
		return nil
	}
	ctx := m.io().replace(&m.io().catalog)
	return func() tea.Msg {
		defer trace.Span("catalog.load")()
		if ctx.Err() != nil {
			return nil
		}
		layout, errs := LoadSidebarLayout("")
		definitions, defErrs := space.LoadDefinitions(config.SpaceDefinitionsDir())
		errs = append(errs, defErrs...)
		if ctx.Err() != nil {
			return nil
		}
		return catalogLoadedMsg{layout: layout, definitions: definitions, errs: errs}
	}
}

func (m *model) startSnapshot() tea.Cmd {
	if m.quitting || m.snapshotInFlight {
		return nil
	}
	m.snapshotInFlight = true
	m.snapshotSeq++
	seq := m.snapshotSeq
	ctx := m.io().replace(&m.io().snapshot)
	if !m.snapshotReady {
		// The first snapshot is what the user waits for; later polls are not.
		ctx = herdr.WithHedge(ctx)
	}
	return func() tea.Msg {
		defer trace.Span("snapshot.load")()
		snapshot, witness, err := herdr.LoadSessionSnapshotContext(ctx)
		if err != nil {
			return snapshotLoadedMsg{seq: seq, liveErr: err}
		}
		history, err := focus.LoadPruned(snapshot, witness)
		if err != nil {
			return snapshotLoadedMsg{seq: seq, liveErr: err}
		}
		state, assocErr := space.LoadAssociationFile(config.StateDir())
		if assocErr != nil {
			return snapshotLoadedMsg{seq: seq, snapshot: snapshot, history: history, catalogErr: assocErr}
		}
		state = space.ReconcileAssociationState(state, witness)
		return snapshotLoadedMsg{seq: seq, snapshot: snapshot, history: history, records: state.Records, unresolved: state.Unresolved}
	}
}

func (m *model) paneReader() func(ctx context.Context, paneID string) (string, error) {
	if m.readPane != nil {
		return m.readPane
	}
	return func(ctx context.Context, paneID string) (string, error) {
		span := trace.Span("preview.read", "pane", paneID)
		result, _, err := herdr.ReadPaneVisibleANSIContext(ctx, paneID)
		if err != nil {
			span("err", err)
			return "", err
		}
		filterSpan := trace.Span("preview.filter", "pane", paneID)
		text := termtext.KeepSGR(result.Text)
		filterSpan("raw", len(result.Text), "filtered", len(text))
		span("raw", len(result.Text), "revision", result.Revision)
		return text, nil
	}
}

// stopPreviewChain cancels the in-flight read and invalidates pending ticks and replies.
func (m *model) stopPreviewChain() {
	m.io().cancelPreview()
	m.previewInFlight = false
	m.previewLoading = false
	m.previewSeq++
}

func (m *model) clearPreview() {
	m.previewText = ""
	m.previewTextLive = false
	m.previewListing = false
	m.previewErr = ""
	m.previewPane = ""
	m.previewDir = ""
	m.previewLoading = false
}

// startPreview reads the selected live pane. refresh=true keeps the current frame with no
// loading indicator (same pane, next poll); refresh=false is a selection change: the last
// frame stays visible until the read lands or the loading delay passes.
func (m *model) startPreview(refresh bool) tea.Cmd {
	if m.quitting || !m.showsPreview() {
		return nil
	}
	item, ok := m.selectedItem()
	if !ok {
		m.stopPreviewChain()
		m.clearPreview()
		return nil
	}
	paneID, dir := previewTarget(item)
	if paneID == "" && dir == "" {
		m.stopPreviewChain()
		m.clearPreview()
		return nil
	}
	if m.previewInFlight && m.previewTargetMatches(item) {
		return nil
	}
	if dir != "" {
		return m.startDirectoryPreview(item, dir)
	}
	m.previewInFlight = true
	m.previewSeq++
	seq := m.previewSeq
	targetID := item.ID
	m.previewPane = paneID
	m.previewDir = ""
	if !refresh {
		m.previewErr = ""
		m.previewLoading = false
	}
	ctx := m.io().replace(&m.io().preview)
	if !refresh {
		ctx = herdr.WithHedge(ctx)
	}
	read := m.paneReader()
	readCmd := func() tea.Msg {
		text, err := read(ctx, paneID)
		if err != nil {
			return previewLoadedMsg{seq: seq, targetID: targetID, paneID: paneID, err: err}
		}
		return previewLoadedMsg{seq: seq, targetID: targetID, paneID: paneID, text: text}
	}
	if refresh {
		return readCmd
	}
	delay := m.previewLoadingDelay
	if delay <= 0 {
		delay = DefaultPreviewLoadingDelay
	}
	loadingCmd := func() tea.Msg {
		timer := time.NewTimer(delay)
		defer timer.Stop()
		select {
		case <-ctx.Done():
			return nil
		case <-timer.C:
			return previewLoadingMsg{seq: seq}
		}
	}
	return tea.Batch(readCmd, loadingCmd)
}

// startDirectoryPreview lists the selected row's directory once. It never polls and never
// touches Herdr. Recovery hints (PreviewText) sit above the listing when present.
func (m *model) startDirectoryPreview(item Item, dir string) tea.Cmd {
	m.stopPreviewChain()
	m.previewInFlight = true
	seq := m.previewSeq
	targetID := item.ID
	header := item.PreviewText
	m.previewPane = ""
	m.previewDir = dir
	m.previewErr = ""
	m.previewLoading = false
	ctx := m.io().replace(&m.io().preview)
	read := m.dirReader()
	readCmd := func() tea.Msg {
		text, err := read(ctx, dir)
		if err != nil {
			return previewLoadedMsg{seq: seq, targetID: targetID, dir: dir, err: err}
		}
		if header != "" {
			text = header + "\n\n" + text
		}
		return previewLoadedMsg{seq: seq, targetID: targetID, dir: dir, text: text}
	}
	delay := m.previewLoadingDelay
	if delay <= 0 {
		delay = DefaultPreviewLoadingDelay
	}
	loadingCmd := func() tea.Msg {
		timer := time.NewTimer(delay)
		defer timer.Stop()
		select {
		case <-ctx.Done():
			return nil
		case <-timer.C:
			return previewLoadingMsg{seq: seq}
		}
	}
	return tea.Batch(readCmd, loadingCmd)
}

func (m *model) dirReader() func(ctx context.Context, dir string) (string, error) {
	if m.readDir != nil {
		return m.readDir
	}
	return dirlist.Read
}

func (m *model) startAccept() tea.Cmd {
	if m.quitting || m.pendingAccept {
		return nil
	}
	item, ok := m.selectedItem()
	if !ok {
		return nil
	}
	// Escape can cancel this only before Herdr accepts the focus write.
	// A request already accepted cannot be undone by closing the socket.
	m.pendingAccept = true
	selectedID := item.ID
	kind := item.Kind
	paneID := item.PaneID
	workspaceID := item.WorkspaceID
	definitionID := item.DefinitionID
	ctx := m.io().replace(&m.io().accept)
	return func() tea.Msg {
		defer trace.Span("accept", "kind", kind)()
		if ctx.Err() != nil {
			return errorMsg{err: ctx.Err()}
		}
		if kind == KindDefinition {
			_, err := space.Open(ctx, definitionID)
			if ctx.Err() != nil {
				return errorMsg{err: ctx.Err()}
			}
			if err != nil {
				return errorMsg{err: err}
			}
			return acceptedMsg{}
		}
		snapshot, witness, err := herdr.LoadSessionSnapshotContext(ctx)
		if err != nil {
			return errorMsg{err: err}
		}
		history, err := focus.LoadPruned(snapshot, witness)
		if err != nil {
			return errorMsg{err: err}
		}
		if ctx.Err() != nil {
			return errorMsg{err: ctx.Err()}
		}
		if kind == KindAgent {
			live, ok := focus.CurrentAgentLiveID(history, paneID)
			if !ok || SelectionID(KindAgent, live.String()) != selectedID {
				return errorMsg{err: fmt.Errorf("hseh focus: selected occupant was replaced")}
			}
			err = herdr.FocusAgentContext(ctx, paneID)
		} else {
			err = herdr.FocusWorkspaceContext(ctx, workspaceID)
		}
		if ctx.Err() != nil {
			return errorMsg{err: ctx.Err()}
		}
		if err != nil {
			return errorMsg{err: err}
		}
		return acceptedMsg{}
	}
}

// afterSelectionChange redirects the preview clock to the selected target. The last
// frame stays on screen; a different pane starts a selection-change read.
func (m *model) afterSelectionChange() tea.Cmd {
	item, ok := m.selectedItem()
	if !ok {
		m.stopPreviewChain()
		m.clearPreview()
		return nil
	}
	paneID, dir := previewTarget(item)
	if !m.previewTargetMatches(item) || (paneID == "" && dir == "") {
		return m.startPreview(false)
	}
	if m.previewInFlight || dir != "" {
		// Same pane still reading, or the same directory already listed: nothing to do.
		return nil
	}
	return m.startPreview(true)
}

func (m *model) applyQuery() {
	m.visible, m.searchScratch = filterItemsInto(m.visible[:0], m.searchScratch, m.allItems, m.query)
	if !HasItemID(m.visible, m.selectedID) {
		m.selectedID = ""
		if m.query == "" {
			m.selectedID = PreselectItemID(m.view, m.visible, m.history, m.launch)
		}
	}
}

// refreshMembership merges fresh catalog rows without reordering rows that merely changed status.
func (m *model) refreshMembership() tea.Cmd {
	fresh := m.catalogItems()
	byID := make(map[string]Item, len(fresh))
	for _, item := range fresh {
		byID[item.ID] = item
	}
	if m.query == "" {
		kept := make([]Item, 0, len(fresh))
		seen := make(map[string]bool, len(fresh))
		for _, item := range m.allItems {
			if next, ok := byID[item.ID]; ok {
				kept = append(kept, next)
				seen[item.ID] = true
			}
		}
		for _, item := range fresh {
			if !seen[item.ID] {
				kept = append(kept, item)
			}
		}
		m.allItems = kept
		m.visible = append(m.visible[:0], kept...)
	} else {
		var matched []Item
		matched, m.searchScratch = filterItemsInto(nil, m.searchScratch, fresh, m.query)
		matchedByID := make(map[string]Item, len(matched))
		for _, item := range matched {
			matchedByID[item.ID] = item
		}
		visible := make([]Item, 0, len(matched))
		seen := make(map[string]bool, len(matched))
		for _, item := range m.visible {
			if next, ok := matchedByID[item.ID]; ok {
				visible = append(visible, next)
				seen[item.ID] = true
			}
		}
		for _, item := range matched {
			if !seen[item.ID] {
				visible = append(visible, item)
			}
		}
		m.allItems = fresh
		m.visible = visible
	}
	item, ok := m.selectedItem()
	if !ok {
		m.selectedID = ""
		m.stopPreviewChain()
		m.clearPreview()
		return nil
	}
	if !m.previewTargetMatches(item) {
		return m.afterSelectionChange()
	}
	return nil
}

func (m *model) moveSelection(delta int) {
	if len(m.visible) == 0 {
		m.selectedID = ""
		return
	}
	index := 0
	for i, item := range m.visible {
		if item.ID == m.selectedID {
			index = i
			break
		}
	}
	index += delta
	if index < 0 {
		index = 0
	}
	if index >= len(m.visible) {
		index = len(m.visible) - 1
	}
	m.selectedID = m.visible[index].ID
}

func (m *model) cycleView(delta int) {
	order := []string{ViewSpaces, ViewAgents}
	index := 0
	for i, view := range order {
		if view == m.view {
			index = i
			break
		}
	}
	index = (index + delta) % len(order)
	if index < 0 {
		index += len(order)
	}
	m.view = order[index]
	m.allItems = m.catalogItems()
	m.applyQuery()
}

// Click-only mouse reporting: normal tracking (1000) with SGR encoding (1006).
// Bubble Tea v1 offers only cell/all-motion modes, so hseh manages this mode itself.
const (
	mouseClickOnlyEnable  = "\x1b[?1000h\x1b[?1006h"
	mouseClickOnlyDisable = "\x1b[?1002l\x1b[?1006l\x1b[?1000l"
)

// Run opens the interactive picker on the given view and blocks until it exits.
func Run(view string) error {
	view, err := ParseView(view)
	if err != nil {
		return err
	}
	poll, configErrs := config.LoadPreviewPollInterval()
	wideMin, moreErrs := config.LoadWidePreviewMinColumns()
	configErrs = append(configErrs, moreErrs...)
	_, _, sizeErrs := config.LoadPopupSize()
	configErrs = append(configErrs, sizeErrs...)
	theme, themeErrs := loadTheme("")
	configErrs = append(configErrs, themeErrs...)
	m := newAsyncModel(view, theme, poll, wideMin, configErrs)
	m.mouseOut = os.Stdout
	defer m.io().cancelAll()
	_, _ = io.WriteString(os.Stdout, mouseClickOnlyEnable)
	defer func() { _, _ = io.WriteString(os.Stdout, mouseClickOnlyDisable) }()
	_, err = tea.NewProgram(m, tea.WithAltScreen()).Run()
	return err
}

content.content:
package picker

import (
	"regexp"
	"strconv"
	"strings"
	"unicode/utf8"

	"github.com/charmbracelet/lipgloss"
	"github.com/charmbracelet/x/ansi"
	"github.com/regutierrez/hseh/internal/termtext"
	"github.com/regutierrez/hseh/internal/trace"
)

const tabRows = 1
const searchRows = 3
const footerRows = 1

// Layout minimums. Side-by-side needs room for both panes; stacked needs a few list rows plus a short preview.
const (
	minListWidth       = 20
	minPreviewWidth    = 20
	minStackedListRows = 3
	minStackedPreview  = 3
	maxStackedPreview  = 8
	minFooterHeight    = 6
)

const searchTitle = " Search "
const searchPrompt = "❯"
const selectionRail = "┃"
const railWidth = 2

const helpText = "↑↓ move · tab view · enter open · esc close"

// pathColumnMinWidth is the narrowest list content that still shows the absolute path column.
// With the default 50/50 split this is a popup of about 94 columns.
const pathColumnMinWidth = 45

const (
	copyLoading        = "Loading…"
	copyLoadFailed     = "Could not load Herdr session"
	copyNoSpaces       = "No spaces open"
	copyNoAgents       = "No agents open"
	copyNoResults      = "No results"
	copyLoadingPreview = "Loading preview…"
	copyNoPreview      = "No preview"
	copyPreviewFailed  = "Preview unavailable"
)

var sgrPattern = regexp.MustCompile(`\x1b\[[0-9:;]*m`)

type previewMode int

const (
	previewHidden previewMode = iota
	previewSide
	previewStacked
)

// frameSpec is the resolved screen geometry for one size. Every renderer and the
// mouse hit-tester read from it so they cannot disagree.
type frameSpec struct {
	mode                                   previewMode
	listY, listW, listH                    int
	searchY, searchW, searchH              int
	dividerX                               int
	stackDividerY                          int
	previewX, previewY, previewW, previewH int
	footerY                                int
}

func (m model) frame() frameSpec {
	width := max(1, m.width)
	height := max(0, m.height)
	f := frameSpec{mode: previewHidden, footerY: -1, listY: tabRows, listW: width, searchW: width}
	if height <= tabRows {
		return f
	}
	footer := 0
	if height >= minFooterHeight {
		footer = footerRows
		f.footerY = height - 1
	}
	rest := height - tabRows - footer
	search := min(searchRows, rest-1)
	if search < 0 {
		search = 0
	}
	f.searchH = search
	f.listH = rest - search
	f.searchY = tabRows + f.listH
	if m.widePreviewMinCols > 0 && width >= m.widePreviewMinCols && width >= minListWidth+1+minPreviewWidth {
		listW := m.splitListWidth
		if listW <= 0 {
			listW = width / 2
		}
		lo, hi := m.splitListBounds()
		listW = min(max(listW, lo), hi)
		f.mode = previewSide
		f.listW = listW
		f.searchW = listW
		f.dividerX = listW
		f.previewX = listW + 1
		f.previewW = width - listW - 1
		f.previewY = tabRows
		f.previewH = rest
		return f
	}
	if width >= minListWidth {
		available := rest - search - 1
		previewH := min(maxStackedPreview, max(minStackedPreview, available/3))
		listH := available - previewH
		if listH >= minStackedListRows && previewH >= minStackedPreview {
			f.mode = previewStacked
			f.listH = listH
			f.searchY = tabRows + listH
			f.stackDividerY = f.searchY + search
			f.previewX = 0
			f.previewY = f.stackDividerY + 1
			f.previewW = width
			f.previewH = previewH
		}
	}
	return f
}

// splitListBounds clamps the side-by-side list width so both panes keep a readable minimum.
func (m model) splitListBounds() (lo, hi int) {
	width := max(1, m.width)
	lo = minListWidth
	hi = width - 1 - minPreviewWidth
	if hi < lo {
		lo, hi = width/2, width/2
	}
	return lo, hi
}

func (m model) renderTabs() string {
	th := m.th()
	var tabs []string
	for _, tab := range []struct{ view, label string }{
		{ViewSpaces, "Spaces"}, {ViewAgents, "Agents"},
	} {
		label := " " + tab.label + " "
		if tab.view == m.view {
			label = th.TabActive + label + "\x1b[0m"
		} else {
			label = th.Muted + label + "\x1b[0m"
		}
		tabs = append(tabs, label)
	}
	return padDisplayWidth(strings.Join(tabs, " "), m.width) + "\x1b[0m"
}

// searchPaneHeight is the rows occupied by the rounded search box, clipped to the terminal.
func (m model) searchPaneHeight() int {
	return m.frame().searchH
}

func (m model) footerHeight() int {
	if m.frame().footerY < 0 {
		return 0
	}
	return footerRows
}

// renderSearch draws the rounded search box: Search title, prompt, caret, and matched/total count.
func (m model) renderSearch(width int) string {
	height := m.searchPaneHeight()
	if height < 1 {
		return ""
	}
	if width < 1 {
		width = 1
	}
	return strings.Join(m.searchBoxLines(width, height), "\n")
}

func (m model) searchBoxLines(width, height int) []string {
	th := m.th()
	minInput := ansi.StringWidth(searchPrompt) + 2 // prompt, space, caret
	if minInput > width {
		minInput = width
	}
	drawBox := height >= 2 && width >= 2+minInput
	borderInner := width
	sidePad := 0
	if drawBox {
		borderInner = width - 2
		if width >= 4+minInput {
			sidePad = 1
		}
	}
	inputInner := width
	if drawBox {
		inputInner = width - 2 - 2*sidePad
	}
	input := m.searchInputLine(inputInner)
	if drawBox {
		pad := strings.Repeat(" ", sidePad)
		input = padDisplayWidth(th.Accent+"│\x1b[0m"+pad+input+pad+th.Accent+"│\x1b[0m", width)
	}
	lines := make([]string, height)
	for i := range lines {
		lines[i] = padDisplayWidth("", width)
	}
	inputIndex := height - 1
	if drawBox && height >= 3 {
		inputIndex = height - 2
	}
	lines[inputIndex] = padDisplayWidth(input, width)
	if drawBox {
		title := ""
		if ansi.StringWidth(searchTitle) <= borderInner {
			title = searchTitle
		}
		lines[0] = searchHorizontalBorder(th.Accent, "╭", "╮", borderInner, title, width)
		if height >= 3 {
			lines[height-1] = searchHorizontalBorder(th.Accent, "╰", "╯", borderInner, "", width)
		}
	}
	return lines
}

func searchHorizontalBorder(color, left, right string, inner int, title string, width int) string {
	var b strings.Builder
	b.WriteString(left)
	if title != "" && inner >= ansi.StringWidth(title) {
		rest := inner - ansi.StringWidth(title)
		leftPad := rest / 2
		b.WriteString(strings.Repeat("─", leftPad))
		b.WriteString(title)
		b.WriteString(strings.Repeat("─", rest-leftPad))
	} else if inner > 0 {
		b.WriteString(strings.Repeat("─", inner))
	}
	b.WriteString(right)
	return padDisplayWidth(color+b.String()+"\x1b[0m", width)
}

// searchInputLine always shows the query; errors live in the footer, never here.
func (m model) searchInputLine(width int) string {
	if width < 1 {
		return ""
	}
	th := m.th()
	text := m.query
	count := strconv.Itoa(len(m.visible)) + " / " + strconv.Itoa(len(m.allItems))
	countWidth := ansi.StringWidth(count)
	promptWidth := ansi.StringWidth(searchPrompt) + 1
	wantPrompt, wantCaret, wantCount := true, true, true
	need := func() int {
		n := 0
		if wantPrompt {
			n += promptWidth
		}
		if wantCaret {
			n++
		}
		if wantCount {
			n += 1 + countWidth
		}
		return n
	}
	if need() > width {
		wantCount = false
	}
	if need() > width {
		wantPrompt = false
	}
	if need() > width {
		wantCaret = false
	}
	textBudget := max(0, width-need())
	visibleText := clipSearchText(text, textBudget, true)
	padW := max(0, width-need()-ansi.StringWidth(visibleText))
	var b strings.Builder
	if wantPrompt {
		b.WriteString(th.Mauve)
		b.WriteString(searchPrompt)
		b.WriteString("\x1b[0m ")
	}
	b.WriteString(visibleText)
	if wantCaret {
		b.WriteString(th.Mauve + "▏\x1b[0m")
	}
	if padW > 0 {
		b.WriteString(strings.Repeat(" ", padW))
	}
	if wantCount {
		b.WriteString(" ")
		b.WriteString(th.Overlay)
		b.WriteString(count)
		b.WriteString("\x1b[0m")
	}
	return padDisplayWidth(b.String(), width)
}

func clipSearchText(s string, width int, keepTail bool) string {
	if width < 1 || s == "" {
		return ""
	}
	if ansi.StringWidth(s) <= width {
		return s
	}
	if !keepTail {
		return ansi.Truncate(s, width, "")
	}
	runes := []rune(s)
	start := 0
	for start < len(runes) && ansi.StringWidth(string(runes[start:])) > width {
		start++
	}
	clipped := string(runes[start:])
	if ansi.StringWidth(clipped) > width {
		return ""
	}
	return clipped
}

// renderFooter shows key help, plus a status. Errors are primary and win over help when
// space is tight; a secondary informational status is dropped before key help.
func (m model) renderFooter(width int) string {
	if width < 1 {
		return ""
	}
	th := m.th()
	help := helpText
	helpW := ansi.StringWidth(help)
	if m.statusErr != "" {
		errText := strings.ReplaceAll(strings.ReplaceAll(m.statusErr, "\n", " "), "\t", " ")
		errW := ansi.StringWidth(errText)
		if errW+2+helpW <= width {
			gap := width - errW - helpW
			return padDisplayWidth(th.Red+errText+"\x1b[0m"+strings.Repeat(" ", gap)+th.Muted+help+"\x1b[0m", width)
		}
		return padDisplayWidth(th.Red+ansi.Truncate(errText, width, "…")+"\x1b[0m", width)
	}
	status := m.secondaryStatus()
	statusW := ansi.StringWidth(status)
	if status != "" && statusW+2+helpW <= width {
		gap := width - statusW - helpW
		return padDisplayWidth(th.Muted+status+"\x1b[0m"+strings.Repeat(" ", gap)+th.Muted+help+"\x1b[0m", width)
	}
	return padDisplayWidth(th.Muted+ansi.Truncate(help, width, "…")+"\x1b[0m", width)
}

func (m model) secondaryStatus() string {
	switch {
	case !m.snapshotReady:
		return "Loading Herdr session…"
	case !m.catalogReady:
		return "Loading definitions…"
	}
	return ""
}

func (m model) View() string {
	if m.width == 0 {
		return "hseh"
	}
	return m.renderView()
}

func (m model) renderView() (out string) {
	if trace.Enabled() {
		span := trace.Span("view")
		defer func() { span("bytes", len(out)) }()
	}
	f := m.frame()
	tabs := m.renderTabs()
	if m.height > 0 && m.height <= tabRows {
		return tabs
	}
	th := m.th()
	search := m.renderSearch(f.searchW)
	var lines []string
	lines = append(lines, tabs)
	switch f.mode {
	case previewSide:
		var listLines, searchLines, prevLines []string
		if f.listH > 0 {
			listLines = strings.Split(m.renderList(f.listW, f.listH), "\n")
		}
		if f.searchH > 0 {
			searchLines = strings.Split(search, "\n")
		}
		prevLines = strings.Split(m.renderPreview(f.previewW, f.previewH), "\n")
		for i := 0; i < f.previewH; i++ {
			left, right := "", ""
			if i < f.listH {
				if i < len(listLines) {
					left = listLines[i]
				}
			} else if si := i - f.listH; si >= 0 && si < len(searchLines) {
				left = searchLines[si]
			}
			if i < len(prevLines) {
				right = prevLines[i]
			}
			lines = append(lines, padDisplayWidth(left, f.listW)+th.Overlay+"│\x1b[0m"+padDisplayWidth(right, f.previewW))
		}
	default:
		if f.listH > 0 {
			lines = append(lines, strings.Split(m.renderList(f.listW, f.listH), "\n")...)
		}
		if f.searchH > 0 {
			lines = append(lines, strings.Split(search, "\n")...)
		}
		if f.mode == previewStacked {
			lines = append(lines, padDisplayWidth(th.Overlay+strings.Repeat("─", f.previewW)+"\x1b[0m", f.previewW))
			lines = append(lines, strings.Split(m.renderPreview(f.previewW, f.previewH), "\n")...)
		}
	}
	if f.footerY >= 0 {
		lines = append(lines, m.renderFooter(m.width))
	}
	return strings.Join(lines, "\n")
}

type listLayout struct {
	Lines   []string
	ItemIDs []string
}

func (m model) listPaneWidth() int {
	return m.frame().listW
}

func (m model) bodyHeight() int {
	return max(1, m.frame().listH)
}

func (m model) previewBodyHeight() int {
	return max(1, m.frame().previewH)
}

func (m model) renderList(width, height int) string {
	layout := m.buildListLayout(width, height)
	return strings.Join(layout.Lines, "\n")
}

func (m model) emptyListCopy() string {
	th := m.th()
	switch {
	case !m.snapshotReady && m.liveErr != "":
		return th.Red + copyLoadFailed + "\x1b[0m"
	case !m.snapshotReady:
		return th.Yellow + copyLoading + "\x1b[0m"
	case strings.TrimSpace(m.query) != "":
		return th.Yellow + copyNoResults + " for “" + m.query + "”\x1b[0m"
	case m.view == ViewAgents:
		return th.Yellow + copyNoAgents + "\x1b[0m"
	default:
		return th.Yellow + copyNoSpaces + "\x1b[0m"
	}
}

// wrapItemBlock wraps one item's display rows to the content width, highlighting query
// matches and, for the selected item, emboldening the primary row.
func (m model) wrapItemBlock(item Item, selected bool, contentWidth int) []string {
	if contentWidth < pathColumnMinWidth {
		item = item.withoutPathColumn()
	}
	rows := highlightItemRows(item, m.query, m.th().Mauve+"\x1b[1m")
	if len(rows) == 0 {
		rows = []string{item.ID}
	}
	var lines []string
	for i, row := range rows {
		if selected && i == 0 {
			row = emboldenAfterResets(row)
		}
		if item.Path != "" {
			// Spaces rows stay one line: a long path is cut, never wrapped onto a second row.
			lines = append(lines, ansi.Truncate(row, contentWidth, "…"))
			continue
		}
		lines = append(lines, wrapDisplayLine(row, contentWidth)...)
	}
	return lines
}

type listWindowResult struct {
	lines, ids     []string
	lowest         int // smallest visible item index (nearest the search box)
	highest        int // largest visible item index (nearest the top)
	partialLowest  bool
	partialHighest bool
}

// fillListWindow wraps only the blocks that can be visible: the anchor block first, then
// whole/partial blocks toward the bottom (lower rank index), then toward the top.
func (m model) fillListWindow(anchor, budget, contentWidth int) listWindowResult {
	n := len(m.visible)
	res := listWindowResult{lowest: anchor, highest: anchor}
	if budget < 1 || n == 0 {
		return res
	}
	block := m.wrapItemBlock(m.visible[anchor], m.visible[anchor].ID == m.selectedID, contentWidth)
	if len(block) > budget {
		block = block[:budget]
	}
	used := len(block)
	var below, belowIDs []string
	for i := anchor - 1; i >= 0 && used < budget; i-- {
		room := budget - used - 1
		if room < 1 {
			break
		}
		blk := m.wrapItemBlock(m.visible[i], m.visible[i].ID == m.selectedID, contentWidth)
		partial := len(blk) > room
		if partial {
			blk = blk[:room]
		}
		below = append(below, "")
		belowIDs = append(belowIDs, "")
		below = append(below, blk...)
		for range blk {
			belowIDs = append(belowIDs, m.visible[i].ID)
		}
		used += 1 + len(blk)
		res.lowest = i
		if partial {
			res.partialLowest = true
			break
		}
	}
	var aboveRev, aboveRevIDs [][]string
	for i := anchor + 1; i < n && used < budget; i++ {
		room := budget - used - 1
		if room < 1 {
			break
		}
		blk := m.wrapItemBlock(m.visible[i], m.visible[i].ID == m.selectedID, contentWidth)
		partial := len(blk) > room
		if partial {
			blk = blk[len(blk)-room:]
		}
		ids := make([]string, len(blk))
		for j := range ids {
			ids[j] = m.visible[i].ID
		}
		aboveRev = append(aboveRev, blk)
		aboveRevIDs = append(aboveRevIDs, ids)
		used += 1 + len(blk)
		res.highest = i
		if partial {
			res.partialHighest = true
			break
		}
	}
	for i := len(aboveRev) - 1; i >= 0; i-- {
		res.lines = append(res.lines, aboveRev[i]...)
		res.ids = append(res.ids, aboveRevIDs[i]...)
		res.lines = append(res.lines, "")
		res.ids = append(res.ids, "")
	}
	res.lines = append(res.lines, block...)
	for range block {
		res.ids = append(res.ids, m.visible[anchor].ID)
	}
	res.lines = append(res.lines, below...)
	res.ids = append(res.ids, belowIDs...)
	return res
}

// buildListLayout places highest-ranked item blocks nearest the bottom search box.
// Rows inside each block stay top-to-bottom; only block order is reversed. Only rows that
// can be on screen are wrapped.
func (m model) buildListLayout(width, height int) listLayout {
	height = max(1, height)
	width = max(1, width)
	th := m.th()
	n := len(m.visible)
	if n == 0 {
		lines := padToHeight(nil, height)
		ids := make([]string, height)
		lines[height-1] = padDisplayWidth(strings.Repeat(" ", railWidth)+m.emptyListCopy(), width) + "\x1b[0m"
		for i := 0; i < height-1; i++ {
			lines[i] = padDisplayWidth("", width) + "\x1b[0m"
		}
		return listLayout{Lines: lines, ItemIDs: ids}
	}
	anchor := 0
	for i, item := range m.visible {
		if item.ID == m.selectedID {
			anchor = i
			break
		}
	}
	contentWidth := max(1, width-railWidth)
	reserve := 0
	var res listWindowResult
	var moreAbove, moreBelow int
	for attempt := 0; attempt < 3; attempt++ {
		res = m.fillListWindow(anchor, height-reserve, contentWidth)
		moreAbove = n - 1 - res.highest
		moreBelow = res.lowest
		want := 0
		if moreAbove > 0 || res.partialHighest {
			want++
		}
		if moreBelow > 0 || res.partialLowest {
			want++
		}
		if want == reserve || height-want < 1 {
			break
		}
		reserve = want
	}
	var lines, ids []string
	if reserve > 0 && (moreAbove > 0 || res.partialHighest) {
		lines = append(lines, th.Overlay+"↑ "+strconv.Itoa(max(moreAbove, 1))+" more\x1b[0m")
		ids = append(ids, "")
	}
	lines = append(lines, res.lines...)
	ids = append(ids, res.ids...)
	if reserve > 0 && (moreBelow > 0 || res.partialLowest) {
		lines = append(lines, th.Overlay+"↓ "+strconv.Itoa(max(moreBelow, 1))+" more\x1b[0m")
		ids = append(ids, "")
	}
	if len(lines) < height {
		pad := height - len(lines)
		lines = append(make([]string, pad), lines...)
		ids = append(make([]string, pad), ids...)
	}
	lines = lines[:height]
	ids = ids[:height]
	rail := th.Accent + selectionRail + "\x1b[0m "
	blank := strings.Repeat(" ", railWidth)
	for i, line := range lines {
		if ids[i] != "" && ids[i] == m.selectedID {
			lines[i] = padDisplayWidth(rail+line, width) + "\x1b[0m"
		} else {
			lines[i] = padDisplayWidth(blank+line, width) + "\x1b[0m"
		}
	}
	return listLayout{Lines: lines, ItemIDs: ids}
}

func (m model) itemIDAtMouse(x, y int) string {
	f := m.frame()
	if f.listH < 1 || y < f.listY || y >= f.listY+f.listH {
		return ""
	}
	if x < 0 || x >= f.listW {
		return ""
	}
	layout := m.buildListLayout(f.listW, f.listH)
	row := y - f.listY
	if row < 0 || row >= len(layout.ItemIDs) {
		return ""
	}
	return layout.ItemIDs[row]
}

func (m model) renderPreview(width, height int) string {
	th := m.th()
	switch {
	case m.previewLoading:
		return clipBlock(th.Yellow+copyLoadingPreview+"\x1b[0m", width, height)
	case m.previewErr != "":
		return clipBlock(th.Red+copyPreviewFailed+"\x1b[0m\n"+th.Muted+m.previewErr+"\x1b[0m", width, height)
	case m.previewText == "":
		if !m.snapshotReady {
			return clipBlock(th.Yellow+copyLoading+"\x1b[0m", width, height)
		}
		return clipBlock(th.Muted+copyNoPreview+"\x1b[0m", width, height)
	case m.previewTextLive:
		return clipLivePreview(m.previewText, width, height)
	case m.previewListing:
		return clipListing(m.previewText, width, height)
	default:
		return clipBlock(m.previewText, width, height)
	}
}

// clipLivePreview preserves terminal rows and shows their bottom edge, rather than reflowing a terminal grid.
func clipLivePreview(text string, width, height int) string {
	width, height = max(1, width), max(1, height)
	lines := strings.Split(strings.TrimSuffix(termtext.KeepSGR(text), "\n"), "\n")
	start := max(0, len(lines)-height)
	var visible []string
	carry := ""
	for i, line := range lines {
		if i >= start {
			visible = append(visible, padDisplayWidth(carry+line, width)+"\x1b[0m")
		}
		// Replay source styles at each row boundary, including styles set above the crop.
		carry = continueSGR(carry, line)
	}
	return joinPaddedRows(visible, width, height)
}

// clipListing shows the top of a directory listing and truncates long entries instead of wrapping them.
func clipListing(text string, width, height int) string {
	width, height = max(1, width), max(1, height)
	lines := strings.Split(strings.TrimSuffix(text, "\n"), "\n")
	if len(lines) > height {
		lines = lines[:height]
	}
	for i, line := range lines {
		lines[i] = padDisplayWidth(line, width) + "\x1b[0m"
	}
	return joinPaddedRows(lines, width, height)
}

func continueSGR(carry, line string) string {
	for _, sgr := range sgrPattern.FindAllString(line, -1) {
		if sgr == "\x1b[m" || sgr == "\x1b[0m" {
			carry = ""
		} else {
			carry += sgr
		}
	}
	return carry
}

// emboldenAfterResets makes a styled row bold without erasing its own colors.
func emboldenAfterResets(line string) string {
	line = strings.ReplaceAll(line, "\x1b[0m", "\x1b[0m\x1b[1m")
	line = strings.ReplaceAll(line, "\x1b[m", "\x1b[m\x1b[1m")
	return "\x1b[1m" + line
}

// highlightItemRows returns display rows with query matches highlighted. Fuzzy match
// offsets map onto plain rows; when a display row's visible text diverges from its
// plain row, the whole query is highlighted as a case-insensitive substring instead.
func highlightItemRows(item Item, query, style string) []string {
	rows := item.DisplayRows
	if len(rows) == 0 {
		rows = item.Rows
	}
	query = strings.TrimSpace(query)
	if query == "" || len(rows) == 0 {
		return rows
	}
	out := make([]string, len(rows))
	perRow := matchedRunesByRow(item, len(rows))
	for i, row := range rows {
		set := perRow[i]
		if set == nil || i >= len(item.Rows) || termtext.StripControls(row) != item.Rows[i] {
			set = substringRuneMatches(termtext.StripControls(row), query)
		}
		if len(set) == 0 {
			out[i] = row
			continue
		}
		out[i] = highlightVisibleRunes(row, set, style)
	}
	return out
}

// matchedRunesByRow converts SearchText byte offsets into per-row visible rune indexes.
func matchedRunesByRow(item Item, rowCount int) []map[int]bool {
	perRow := make([]map[int]bool, rowCount)
	if len(item.Matches) == 0 || len(item.Rows) == 0 {
		return perRow
	}
	start := 0
	for r, plain := range item.Rows {
		if r >= rowCount {
			break
		}
		end := start + len(plain)
		for _, b := range item.Matches {
			if b >= start && b < end {
				if perRow[r] == nil {
					perRow[r] = map[int]bool{}
				}
				perRow[r][utf8.RuneCountInString(plain[:b-start])] = true
			}
		}
		start = end + 1 // joined with a single space
	}
	return perRow
}

func substringRuneMatches(plain, query string) map[int]bool {
	text := []rune(strings.ToLower(plain))
	q := []rune(strings.ToLower(query))
	if len(q) == 0 || len(q) > len(text) {
		return nil
	}
	var set map[int]bool
	for i := 0; i+len(q) <= len(text); {
		if string(text[i:i+len(q)]) == string(q) {
			if set == nil {
				set = map[int]bool{}
			}
			for j := 0; j < len(q); j++ {
				set[i+j] = true
			}
			i += len(q)
			continue
		}
		i++
	}
	return set
}

// highlightVisibleRunes styles the visible runes at the given indexes, keeping existing SGR
// state by replaying it after each highlighted rune.
func highlightVisibleRunes(line string, set map[int]bool, style string) string {
	var b strings.Builder
	b.Grow(len(line) + 16*len(set))
	carry := ""
	index := 0
	for i := 0; i < len(line); {
		if line[i] == 0x1b {
			if loc := sgrPattern.FindStringIndex(line[i:]); loc != nil && loc[0] == 0 {
				sgr := line[i : i+loc[1]]
				b.WriteString(sgr)
				carry = continueSGR(carry, sgr)
				i += loc[1]
				continue
			}
			b.WriteByte(line[i])
			i++
			continue
		}
		r, size := utf8.DecodeRuneInString(line[i:])
		if set[index] {
			b.WriteString(style)
			b.WriteString(line[i : i+size])
			b.WriteString("\x1b[0m")
			b.WriteString(carry)
		} else {
			b.WriteString(line[i : i+size])
		}
		_ = r
		index++
		i += size
	}
	return b.String()
}

func wrapDisplayLine(line string, width int) []string {
	if width <= 0 {
		return []string{line}
	}
	wrapped := ansi.Hardwrap(line, width, false)
	if wrapped == "" {
		return []string{""}
	}
	lines := strings.Split(wrapped, "\n")
	carry := ""
	for i, line := range lines {
		lines[i] = carry + line
		carry = continueSGR(carry, line)
	}
	return lines
}

func padDisplayWidth(line string, width int) string {
	if width <= 0 {
		return ""
	}
	line = ansi.Truncate(line, width, "")
	return lipgloss.NewStyle().Width(width).MaxHeight(1).Render(line)
}

func padToHeight(lines []string, height int) []string {
	for len(lines) < height {
		lines = append(lines, "")
	}
	if len(lines) > height {
		lines = lines[:height]
	}
	return lines
}

// joinPaddedRows pads every row, including empty filler, so stacked preview
// lines clear stale cells instead of emitting zero-width blanks.
func joinPaddedRows(lines []string, width, height int) string {
	lines = padToHeight(lines, height)
	for i, line := range lines {
		if ansi.StringWidth(line) == width {
			continue
		}
		lines[i] = padDisplayWidth(line, width)
	}
	return strings.Join(lines, "\n")
}

func clipBlock(text string, width, height int) string {
	if width < 1 {
		width = 1
	}
	if height < 1 {
		height = 1
	}
	var lines []string
	for _, line := range strings.Split(text, "\n") {
		lines = append(lines, wrapDisplayLine(line, width)...)
		if len(lines) >= height {
			break
		}
	}
	for i, line := range lines {
		if i >= height {
			break
		}
		lines[i] = padDisplayWidth(line, width)
	}
	return joinPaddedRows(lines, width, height)
}

