package picker

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"github.com/regutierrez/hseh/internal/focus"
	"github.com/regutierrez/hseh/internal/gitinfo"
	"github.com/regutierrez/hseh/internal/herdr"
	"github.com/regutierrez/hseh/internal/termtext"
	"github.com/sahilm/fuzzy"
)

const (
	KindSpace      = "space"
	KindAgent      = "agent"
	KindDefinition = "definition"
	ViewSpaces     = "spaces"
	ViewAgents     = "agents"
)

// Spaces rows carry a source badge: a live Herdr workspace or an unopened template.
const (
	SourceHerdr    = "herdr"
	SourceTemplate = "template"
)

// Item is one flat picker row with a stable target id.
type Item struct {
	Kind         string `json:"kind"`
	ID           string `json:"id"`
	WorkspaceID  string `json:"workspace_id,omitempty"`
	PaneID       string `json:"pane_id,omitempty"`
	DefinitionID string `json:"definition_id,omitempty"`
	Label        string `json:"label,omitempty"`
	Status       string `json:"status,omitempty"`
	// Source and Path are set on Spaces rows only. Path is absolute and is what the preview lists.
	Source string `json:"source,omitempty"`
	Path   string `json:"path,omitempty"`
	// Recovery holds the exact `hseh recover` commands for an unresolved template; the popup shows them in the preview.
	Recovery    []string `json:"recovery,omitempty"`
	Rows        []string `json:"rows"`
	DisplayRows []string `json:"-"`
	SearchText  string   `json:"-"`
	PreviewPane string   `json:"-"`
	PreviewText string   `json:"-"`
	// Matches are byte offsets into SearchText matched by the current query, used for highlighting.
	Matches []int `json:"-"`
}

// ListDocument is the public JSON listing shape.
type ListDocument struct {
	Session ListSession `json:"session"`
	View    string      `json:"view"`
	Items   []Item      `json:"items"`
	Errors  []string    `json:"errors,omitempty"`
}

// ListSession names the Herdr session the listing came from.
type ListSession struct {
	Name       string `json:"name"`
	SocketPath string `json:"socket_path"`
}

func sidebarLayoutFromNameRows(spaceRows, agentRows [][]string) SidebarLayout {
	layout := defaultSidebarLayout()
	if len(spaceRows) > 0 {
		layout.SpaceRows = tokensFromNames(spaceRows)
	}
	if len(agentRows) > 0 {
		layout.AgentRows = tokensFromNames(agentRows)
	}
	return layout
}

// BuildItems builds Spaces or Agents rows from live snapshot plus history.
func BuildItems(view string, snapshot herdr.SessionSnapshot, history focus.History, spaceRows, agentRows [][]string) []Item {
	return BuildItemsWithLayout(view, snapshot, history, sidebarLayoutFromNameRows(spaceRows, agentRows))
}

// BuildItemsWithLayout uses a parsed sidebar layout for styles and per-agent rows.
func BuildItemsWithLayout(view string, snapshot herdr.SessionSnapshot, history focus.History, layout SidebarLayout) []Item {
	spaces := buildSpaceItems(snapshot, history, layout)
	agents := buildAgentItems(snapshot, history, layout)
	switch view {
	case ViewAgents:
		return agents
	default:
		return spaces
	}
}

func buildSpaceItems(snapshot herdr.SessionSnapshot, history focus.History, layout SidebarLayout) []Item {
	indexOf := map[string]int{}
	for i, id := range history.Spaces {
		indexOf[id] = i
	}
	workspaces := append([]herdr.WorkspaceRow{}, snapshot.Workspaces...)
	sort.SliceStable(workspaces, func(i, j int) bool {
		left, leftOK := indexOf[workspaces[i].WorkspaceID]
		right, rightOK := indexOf[workspaces[j].WorkspaceID]
		if leftOK && rightOK {
			return left < right
		}
		if leftOK {
			return true
		}
		if rightOK {
			return false
		}
		return i < j
	})
	var items []Item
	for _, workspace := range workspaces {
		dir := herdr.ActiveWorkspaceDirectory(snapshot, workspace.WorkspaceID)
		git := snapshot.GitByDirectory[dir]
		// The checkout root is stable while the user moves around inside a repository.
		path := firstNonEmpty(git.Root, dir)
		name := sanitizeTokenValue(firstNonEmpty(workspace.Label, workspace.WorkspaceID))
		plain, display := renderSpaceRow(spaceRow{status: workspace.AgentStatus, source: SourceHerdr, name: name, git: git, path: path}, layout)
		items = append(items, Item{
			Kind:        KindSpace,
			ID:          SelectionID(KindSpace, workspace.WorkspaceID),
			WorkspaceID: workspace.WorkspaceID,
			Label:       termtext.StripControls(workspace.Label),
			Status:      workspace.AgentStatus,
			Source:      SourceHerdr,
			Path:        path,
			Rows:        []string{plain},
			DisplayRows: []string{display},
			SearchText:  plain,
		})
	}
	return items
}

func buildAgentItems(snapshot herdr.SessionSnapshot, history focus.History, layout SidebarLayout) []Item {
	agents := append([]herdr.AgentRow{}, snapshot.Agents...)
	sort.SliceStable(agents, func(i, j int) bool {
		left := focus.AgentPriorityRank(agents[i].AgentStatus)
		right := focus.AgentPriorityRank(agents[j].AgentStatus)
		if left != right {
			return left < right
		}
		if agents[i].StateChangeSeq != agents[j].StateChangeSeq {
			return agents[i].StateChangeSeq > agents[j].StateChangeSeq
		}
		return i < j
	})
	var items []Item
	for _, agent := range agents {
		liveID, ok := focus.CurrentAgentLiveID(history, agent.PaneID)
		if !ok {
			liveID = focus.AgentLiveID{PaneID: agent.PaneID, Generation: 1}
		}
		plain, display := renderAgentSidebarRows(snapshot, agent, layout)
		items = append(items, Item{
			Kind:        KindAgent,
			ID:          SelectionID(KindAgent, liveID.String()),
			WorkspaceID: agent.WorkspaceID,
			PaneID:      agent.PaneID,
			Label:       firstNonEmpty(agent.DisplayAgent, agent.Title, agent.Agent, agent.PaneID),
			Status:      agent.AgentStatus,
			Rows:        plain,
			DisplayRows: display,
			SearchText:  strings.Join(plain, " "),
			PreviewPane: agent.PaneID,
		})
	}
	return items
}

func sanitizeTokenValue(value string) string {
	return strings.TrimSpace(termtext.StripControls(value))
}

// spaceRow is the content of one single-line Spaces row: status slot, source badge, name, git, path.
type spaceRow struct {
	status string
	source string
	name   string
	tag    string // muted note after the name, e.g. "recovery needed"
	git    gitinfo.WorkspaceGit
	path   string
}

// Nerd Fonts 3 glyphs for the source badge: nf-md-sheep (as in sesh) and nf-md-content_copy.
const (
	herdrSourceIcon    = "\U000f0cc6"
	templateSourceIcon = "\U000f018f"
)

// statusSlotWidth keeps badges aligned whether or not a row has an agent status icon.
const statusSlotWidth = 2

// badgeColumnWidth fits the widest badge ("<icon> template") plus one separator cell.
var badgeColumnWidth = len([]rune(templateSourceIcon+" "+SourceTemplate)) + 1

// pathSeparator sits between the row body and the absolute path so the renderer can drop the path column.
const pathSeparator = "  "

func sourceBadge(source string) string {
	switch source {
	case SourceHerdr:
		return herdrSourceIcon + " " + SourceHerdr
	case SourceTemplate:
		return templateSourceIcon + " " + SourceTemplate
	default:
		return ""
	}
}

func renderSpaceRow(row spaceRow, layout SidebarLayout) (plain, display string) {
	prefix, styledPrefix := statePrefix(row.status, layout.StatusIndicators)
	if prefix == "" {
		prefix = strings.Repeat(" ", statusSlotWidth)
		styledPrefix = prefix
	}
	badge := sourceBadge(row.source)
	badge += strings.Repeat(" ", max(0, badgeColumnWidth-len([]rune(badge))))
	plain = prefix + badge + row.name
	display = styledPrefix + mutedSGR + badge + "\x1b[0m" + "\x1b[1m" + row.name + "\x1b[0m"
	if row.tag != "" {
		plain += " (" + row.tag + ")"
		display += " " + mutedSGR + "(" + row.tag + ")" + "\x1b[0m"
	}
	if detail := strings.TrimSpace(row.git.Branch + " " + row.git.Status); detail != "" {
		if row.git.Branch != "" {
			detail = gitBranchIcon + " " + detail
		}
		plain += "  " + detail
		display += "  " + mutedSGR + detail + "\x1b[0m"
	}
	if row.path != "" {
		plain += pathSeparator + row.path
		display += pathSeparator + mutedSGR + row.path + "\x1b[0m"
	}
	return plain, display
}

// withoutPathColumn drops the trailing path from a Spaces row for narrow lists.
// Search text keeps the path so fuzzy matches on it still rank the row.
func (item Item) withoutPathColumn() Item {
	if item.Path == "" || len(item.Rows) == 0 {
		return item
	}
	rows := append([]string{}, item.Rows...)
	rows[0] = strings.TrimSuffix(rows[0], pathSeparator+item.Path)
	item.Rows = rows
	if len(item.DisplayRows) > 0 {
		display := append([]string{}, item.DisplayRows...)
		display[0] = strings.TrimSuffix(display[0], pathSeparator+mutedSGR+item.Path+"\x1b[0m")
		item.DisplayRows = display
	}
	return item
}

func renderAgentSidebarRows(snapshot herdr.SessionSnapshot, agent herdr.AgentRow, layout SidebarLayout) (plain, display []string) {
	workspaceLabel := agent.WorkspaceID
	if workspace, ok := herdr.WorkspaceByID(snapshot, agent.WorkspaceID); ok && workspace.Label != "" {
		workspaceLabel = workspace.Label
	}
	tabLabel := ""
	if tab, ok := herdr.TabByID(snapshot, agent.TabID); ok {
		tabLabel = tab.Label
	}
	values := map[string]string{
		"state_text":              sanitizeTokenValue(firstNonEmpty(agent.StateLabels[agent.AgentStatus], agent.AgentStatus)),
		"workspace":               sanitizeTokenValue(workspaceLabel),
		"tab":                     sanitizeTokenValue(tabLabel),
		"pane":                    sanitizeTokenValue(agent.Label),
		"agent":                   sanitizeTokenValue(firstNonEmpty(agent.DisplayAgent, agent.Agent)),
		"terminal_title":          sanitizeTokenValue(agent.TerminalTitle),
		"terminal_title_stripped": sanitizeTokenValue(agent.TitleStripped),
	}
	if agent.AgentStatus != "" {
		values["state_icon"] = stateIconGlyph(agent.AgentStatus, layout.StatusIndicators)
	}
	for name, token := range agent.Tokens {
		values["$"+name] = sanitizeTokenValue(token)
	}
	rows := layout.AgentRows
	if override, ok := layout.AgentRowsByAgent[agent.Agent]; ok {
		rows = override
	}
	// Keep Herdr's configured description rows, including per-harness overrides and reported tokens.
	var details []string
	if len(rows) > 1 {
		details, _ = renderSidebarRows(rows[1:], values, agent.AgentStatus)
	}
	prefix, styledPrefix := statePrefix(agent.AgentStatus, layout.StatusIndicators)
	heading := agentHarnessIcon(agent.Agent) + " " + sanitizeTokenValue(firstNonEmpty(tabLabel, agent.Label, agent.PaneID))
	location := sanitizeTokenValue(workspaceLabel)
	if dir := abbreviatedDirectory(firstNonEmpty(agent.ForegroundCwd, agent.Cwd)); dir != "" {
		location += " (" + sanitizeTokenValue(dir) + ")"
	}
	plain = []string{prefix + heading, location}
	display = []string{styledPrefix + heading, mutedSGR + location + "\x1b[0m"}
	if description := strings.Join(details, " "); description != "" {
		plain = append(plain, description)
		display = append(display, mutedSGR+description+"\x1b[0m")
	}
	return plain, display
}

func renderTokenRows(layout [][]string, values map[string]string) []string {
	sanitized := map[string]string{}
	for key, value := range values {
		sanitized[key] = sanitizeTokenValue(value)
	}
	plain, _ := renderSidebarRows(tokensFromNames(layout), sanitized, sanitized["state_text"])
	return plain
}

func renderSidebarRows(layout [][]SidebarToken, values map[string]string, status string) (plain, display []string) {
	for _, cells := range layout {
		var plainParts []string
		var displayParts []string
		for _, cell := range cells {
			value := values[cell.Name]
			if value == "" {
				continue
			}
			plainParts = append(plainParts, value)
			displayParts = append(displayParts, stylePlainToken(cell, value, status))
		}
		if len(plainParts) == 0 {
			continue
		}
		plain = append(plain, strings.Join(plainParts, " · "))
		display = append(display, strings.Join(displayParts, " · "))
	}
	return plain, display
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return value
		}
	}
	return ""
}

// FilterItems ranks matching items by fuzzy quality, then original order.
func FilterItems(items []Item, query string) []Item {
	filtered, _ := filterItemsInto(nil, nil, items, query)
	return filtered
}

// filterItemsInto appends matches to dst (reusing its backing array) and reuses
// the search-target scratch slice so per-keystroke filtering does not reallocate.
func filterItemsInto(dst []Item, scratch []string, items []Item, query string) ([]Item, []string) {
	query = strings.TrimSpace(query)
	dst = dst[:0]
	if query == "" {
		dst = append(dst, items...)
		for i := range dst {
			dst[i].Matches = nil
		}
		return dst, scratch
	}
	scratch = scratch[:0]
	for _, item := range items {
		scratch = append(scratch, item.SearchText)
	}
	matches := fuzzy.Find(query, scratch)
	sort.SliceStable(matches, func(i, j int) bool {
		if matches[i].Score != matches[j].Score {
			return matches[i].Score > matches[j].Score
		}
		return matches[i].Index < matches[j].Index
	})
	for _, match := range matches {
		item := items[match.Index]
		item.Matches = match.MatchedIndexes
		dst = append(dst, item)
	}
	return dst, scratch
}

func EncodeListJSON(doc ListDocument) ([]byte, error) {
	if doc.Items == nil {
		doc.Items = []Item{}
	}
	return json.MarshalIndent(doc, "", "  ")
}

func ParseView(view string) (string, error) {
	switch view {
	case "", ViewSpaces:
		return ViewSpaces, nil
	case ViewAgents:
		return ViewAgents, nil
	default:
		return "", fmt.Errorf("hseh: invalid view %s", view)
	}
}
package picker

import (
	"os"
	"strings"

	"github.com/regutierrez/hseh/internal/focus"
	"github.com/regutierrez/hseh/internal/herdr"
)

type LaunchContext struct {
	FromAgentPane bool
	CurrentSpace  string
	CurrentAgent  string
}

func launchFromEnv(snapshot herdr.SessionSnapshot, history focus.History) LaunchContext {
	ctx := LaunchContext{
		CurrentSpace: snapshot.FocusedWorkspaceID,
	}
	if snapshot.FocusedPaneID != "" {
		if id, ok := focus.CurrentAgentLiveID(history, snapshot.FocusedPaneID); ok {
			ctx.CurrentAgent = id.String()
		}
		for _, agent := range snapshot.Agents {
			if agent.PaneID == snapshot.FocusedPaneID {
				ctx.FromAgentPane = true
				break
			}
		}
	}
	if os.Getenv("HERDR_PLUGIN_CONTEXT_JSON") != "" {
		// focused_pane_agent in context is enough to treat launch as from an agent pane.
		if !ctx.FromAgentPane {
			ctx.FromAgentPane = containsAgentContextJSON(os.Getenv("HERDR_PLUGIN_CONTEXT_JSON"))
		}
	}
	return ctx
}

func containsAgentContextJSON(raw string) bool {
	if strings.Contains(raw, `"focused_pane_agent":null`) || strings.Contains(raw, `"focused_pane_agent":""`) {
		return false
	}
	return strings.Contains(raw, `"focused_pane_agent":"`)
}

// PreselectItemID chooses the previous target, then first non-current, then current.
func PreselectItemID(view string, items []Item, history focus.History, launch LaunchContext) string {
	if len(items) == 0 {
		return ""
	}
	wanted := previousTargetID(view, items, history, launch)
	if wanted != "" && HasItemID(items, wanted) {
		return wanted
	}
	for _, item := range items {
		if !isCurrentItem(item, launch) {
			return item.ID
		}
	}
	return items[0].ID
}

func previousTargetID(view string, items []Item, history focus.History, launch LaunchContext) string {
	switch view {
	case ViewAgents:
		return previousAgentID(history, launch.CurrentAgent, items)
	default:
		return previousSpaceID(history, launch.CurrentSpace, items)
	}
}

func itemTarget(item Item) string {
	switch item.Kind {
	case KindSpace:
		return item.WorkspaceID
	case KindDefinition:
		return item.DefinitionID
	case KindAgent:
		return strings.TrimPrefix(item.ID, KindAgent+":")
	default:
		return item.ID
	}
}

func previousSpaceID(history focus.History, current string, items []Item) string {
	for _, id := range history.Spaces {
		if id == current {
			continue
		}
		for _, item := range items {
			if item.Kind == KindSpace && item.WorkspaceID == id {
				return item.ID
			}
		}
	}
	return ""
}

func previousAgentID(history focus.History, current string, items []Item) string {
	for _, id := range history.Agents {
		s := id.String()
		if s == current {
			continue
		}
		for _, item := range items {
			if item.Kind == KindAgent && itemTarget(item) == s {
				return item.ID
			}
		}
	}
	return ""
}

func isCurrentItem(item Item, launch LaunchContext) bool {
	switch item.Kind {
	case KindSpace:
		return item.WorkspaceID == launch.CurrentSpace || itemTarget(item) == launch.CurrentSpace
	case KindAgent:
		return itemTarget(item) == launch.CurrentAgent
	default:
		return false
	}
}

func HasItemID(items []Item, id string) bool {
	for _, item := range items {
		if item.ID == id {
			return true
		}
	}
	return false
}
package picker

import (
	"context"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/regutierrez/hseh/internal/gitinfo"
	"github.com/regutierrez/hseh/internal/herdr"
	"github.com/regutierrez/hseh/internal/space"
	"github.com/regutierrez/hseh/internal/trace"
)

type gitLoadedMsg struct {
	byDirectory map[string]gitinfo.WorkspaceGit
}

// Git refresh is independent of live status/preview reads. A slow checkout cannot freeze those updates.
func (m *model) startGit() tea.Cmd {
	if m.quitting || m.gitInFlight || m.view == ViewAgents {
		return nil
	}
	m.gitInFlight = true
	snapshot := m.snapshot
	definitions := m.definitions
	ctx := m.io().replace(&m.io().git)
	return func() tea.Msg { return gitLoadedMsg{byDirectory: LoadGit(ctx, snapshot, definitions)} }
}

// LoadGit reads git detail for every live workspace's active directory and every template directory.
func LoadGit(ctx context.Context, snapshot herdr.SessionSnapshot, definitions []space.Definition) map[string]gitinfo.WorkspaceGit {
	byDirectory := map[string]gitinfo.WorkspaceGit{}
	span := trace.Span("git.load")
	dirs := make([]string, 0, len(snapshot.Workspaces)+len(definitions))
	for _, workspace := range snapshot.Workspaces {
		dirs = append(dirs, herdr.ActiveWorkspaceDirectory(snapshot, workspace.WorkspaceID))
	}
	for _, def := range definitions {
		dirs = append(dirs, def.ResolvedDir)
	}
	for _, dir := range dirs {
		if ctx.Err() != nil {
			break
		}
		if dir == "" {
			continue
		}
		if _, exists := byDirectory[dir]; !exists {
			byDirectory[dir] = gitinfo.Read(ctx, dir)
		}
	}
	span("dirs", len(byDirectory))
	return byDirectory
}

