package picker

import (
	"os"
	"path/filepath"
	"strings"
)

const mutedSGR = "\x1b[38;5;245m"

// Nerd Fonts 3 glyph: nf-dev-git_branch.
const gitBranchIcon = "\ue725"

func statePrefix(status, mode string) (plain, display string) {
	if status == "" {
		return "", ""
	}
	icon := stateIconGlyph(status, mode)
	return icon + " ", stylePlainToken(SidebarToken{Name: "state_icon"}, icon, status) + " "
}

func agentHarnessIcon(agent string) string {
	switch agent {
	case "pi", "omp":
		return "\U000f03ff" // nf-md-pi
	case "claude", "claude-code":
		return "\uec82" // nf-cod-claude, Nerd Fonts 3.5+
	case "codex":
		return "\uec81" // nf-cod-openai, Nerd Fonts 3.5+
	case "amp":
		return "amp"
	case "gemini":
		return "✦"
	case "grok":
		return "grok"
	default:
		return "\U000f018d" // nf-md-console
	}
}

func abbreviatedDirectory(dir string) string {
	if dir == "" {
		return ""
	}
	dir = filepath.Clean(dir)
	home, _ := os.UserHomeDir()
	if home != "" && dir == home {
		return "~"
	}
	if home != "" && strings.HasPrefix(dir, home+string(filepath.Separator)) {
		relative := strings.TrimPrefix(dir, home+string(filepath.Separator))
		if filepath.Dir(relative) == "." {
			return "~/" + relative
		}
		return "~/…/" + filepath.Base(dir)
	}
	if dir == string(filepath.Separator) {
		return dir
	}
	if filepath.IsAbs(dir) {
		if filepath.Dir(dir) == string(filepath.Separator) {
			return dir
		}
		return "/…/" + filepath.Base(dir)
	}
	return dir
}
package picker

import (
	"path/filepath"
	"sort"
	"strings"

	"github.com/regutierrez/hseh/internal/gitinfo"
	"github.com/regutierrez/hseh/internal/herdr"
	"github.com/regutierrez/hseh/internal/space"
)

func SelectionID(kind, target string) string {
	return kind + ":" + target
}

func definitionItem(def space.Definition, needsRecovery bool, git gitinfo.WorkspaceGit) Item {
	name := space.SanitizeDisplayText(def.Name)
	desc := space.SanitizeDisplayText(def.Description)
	dir := space.SanitizeDisplayText(def.ResolvedDir)
	if dir == "" {
		dir = space.SanitizeDisplayText(def.WorkingDir)
	}
	row := spaceRow{source: SourceTemplate, name: name, git: git, path: dir}
	var recovery []string
	preview := ""
	if needsRecovery {
		hints := space.RecoveryHintLines(def.ID)
		row.tag = hints[0]
		recovery = hints[1:]
		preview = strings.Join(hints, "\n")
	}
	plain, display := renderSpaceRow(row, defaultSidebarLayout())
	search := strings.Join([]string{plain, desc, space.SanitizeDisplayText(def.SourceFile), space.SanitizeDisplayText(filepath.Base(def.SourceFile))}, " ")
	return Item{
		Kind:         KindDefinition,
		ID:           SelectionID(KindDefinition, def.ID),
		DefinitionID: def.ID,
		Label:        name,
		Source:       SourceTemplate,
		Path:         dir,
		Recovery:     recovery,
		Rows:         []string{plain},
		DisplayRows:  []string{display},
		SearchText:   search,
		PreviewText:  preview,
	}
}

func AppendUnopenedDefinitionItems(items []Item, view string, snapshot herdr.SessionSnapshot, definitions []space.Definition, records, unresolved []space.AssociationRecord) []Item {
	if view == ViewAgents {
		return items
	}
	openKeys := space.AssociatedLiveDefinitionKeys(space.AssociationState{Records: records}, snapshot)
	unresolvedKeys := map[string]bool{}
	for _, record := range unresolved {
		unresolvedKeys[space.AssociationIdentityKey(record.DefinitionID, record.ResolvedDir)] = true
	}
	var extra []Item
	for _, def := range definitions {
		if openKeys[space.AssociationIdentityKey(def.ID, def.ResolvedDir)] {
			continue
		}
		extra = append(extra, definitionItem(def, unresolvedKeys[space.AssociationIdentityKey(def.ID, def.ResolvedDir)], snapshot.GitByDirectory[def.ResolvedDir]))
	}
	sort.SliceStable(extra, func(i, j int) bool { return extra[i].Label < extra[j].Label })
	return append(items, extra...)
}
package picker

import (
	"fmt"
	"os"

	"github.com/BurntSushi/toml"
	"github.com/charmbracelet/lipgloss"
	"github.com/regutierrez/hseh/internal/config"
)

// SidebarToken is one configured sidebar cell, including optional inline style.
type SidebarToken struct {
	Name   string
	Fg     string
	Bold   bool
	Dim    bool
	Styled bool
}

// SidebarLayout is the parsed Herdr sidebar configuration used by the picker.
type SidebarLayout struct {
	SpaceRows        [][]SidebarToken
	AgentRows        [][]SidebarToken
	AgentRowsByAgent map[string][][]SidebarToken
	StatusIndicators string
}

type herdrSidebarFile struct {
	UI struct {
		StatusIndicators string `toml:"status_indicators"`
		Sidebar          struct {
			Agents struct {
				Rows        [][]any            `toml:"rows"`
				RowsByAgent map[string][][]any `toml:"rows_by_agent"`
			} `toml:"agents"`
			Spaces struct {
				Rows [][]any `toml:"rows"`
			} `toml:"spaces"`
		} `toml:"sidebar"`
	} `toml:"ui"`
}

func defaultAgentSidebarRows() [][]string {
	return [][]string{{"state_icon", "machine", "workspace", "tab"}, {"agent"}}
}

func defaultSpaceSidebarRows() [][]string {
	return [][]string{{"state_icon", "workspace"}, {"branch", "git_status"}}
}

func defaultSidebarLayout() SidebarLayout {
	return SidebarLayout{
		SpaceRows:        tokensFromNames(defaultSpaceSidebarRows()),
		AgentRows:        tokensFromNames(defaultAgentSidebarRows()),
		AgentRowsByAgent: map[string][][]SidebarToken{},
		StatusIndicators: "dots",
	}
}

// LoadSidebarLayout reads ui.sidebar rows, rows_by_agent, token styles, and status_indicators.
func LoadSidebarLayout(configPath string) (SidebarLayout, []string) {
	layout := defaultSidebarLayout()
	if configPath == "" {
		configPath = config.HerdrConfigPath()
	}
	payload, err := os.ReadFile(configPath)
	if err != nil {
		if os.IsNotExist(err) {
			return layout, nil
		}
		return layout, []string{fmt.Sprintf("hseh sidebar: read %s: %v", configPath, err)}
	}
	var file herdrSidebarFile
	if err := toml.Unmarshal(payload, &file); err != nil {
		return layout, []string{fmt.Sprintf("hseh sidebar: parse %s: %v", configPath, err)}
	}
	if file.UI.StatusIndicators == "symbols" || file.UI.StatusIndicators == "dots" {
		layout.StatusIndicators = file.UI.StatusIndicators
	}
	if parsed := parseSidebarTokenRows(file.UI.Sidebar.Spaces.Rows); len(parsed) > 0 {
		layout.SpaceRows = parsed
	}
	if parsed := parseSidebarTokenRows(file.UI.Sidebar.Agents.Rows); len(parsed) > 0 {
		layout.AgentRows = parsed
	}
	for agentID, raw := range file.UI.Sidebar.Agents.RowsByAgent {
		if parsed := parseSidebarTokenRows(raw); len(parsed) > 0 {
			layout.AgentRowsByAgent[agentID] = parsed
		}
	}
	return layout, nil
}

func tokensFromNames(rows [][]string) [][]SidebarToken {
	var out [][]SidebarToken
	for _, row := range rows {
		var cells []SidebarToken
		for _, name := range row {
			cells = append(cells, SidebarToken{Name: name})
		}
		out = append(out, cells)
	}
	return out
}

func parseSidebarTokenRows(raw [][]any) [][]SidebarToken {
	var rows [][]SidebarToken
	for _, row := range raw {
		var cells []SidebarToken
		for _, item := range row {
			switch value := item.(type) {
			case string:
				if value != "" {
					cells = append(cells, SidebarToken{Name: value})
				}
			case map[string]any:
				name, _ := value["token"].(string)
				if name == "" {
					continue
				}
				cell := SidebarToken{Name: name, Styled: true}
				if fg, ok := value["fg"].(string); ok {
					cell.Fg = fg
				}
				if bold, ok := value["bold"].(bool); ok {
					cell.Bold = bold
				}
				if dim, ok := value["dim"].(bool); ok {
					cell.Dim = dim
				}
				cells = append(cells, cell)
			}
		}
		if len(cells) > 0 {
			rows = append(rows, cells)
		}
	}
	return rows
}

// Herdr 0.9.0 settings preview in the installed binary:
// color dots  ● ● ● ○ ·
// distinct symbols  × ◐ ✓ ○ ·
func stateIconGlyph(status, mode string) string {
	if mode == "symbols" {
		switch status {
		case "blocked":
			return "×"
		case "working":
			return "◐"
		case "done":
			return "✓"
		case "idle":
			return "○"
		default:
			return "·"
		}
	}
	switch status {
	case "blocked", "working", "done":
		return "●"
	case "idle":
		return "○"
	default:
		return "·"
	}
}

func stateIconColor(status string) string {
	switch status {
	case "blocked":
		return "91"
	case "working":
		return "33"
	case "done":
		return "36"
	case "idle":
		return "32"
	default:
		return "90"
	}
}

func stylePlainToken(token SidebarToken, plain, status string) string {
	if plain == "" {
		return ""
	}
	style := lipgloss.NewStyle()
	colored := false
	if token.Name == "state_icon" && token.Fg == "" {
		// Herdr's terminal theme uses the terminal palette, not CSS color names.
		plain = "\x1b[" + stateIconColor(status) + "m" + plain + "\x1b[0m"
	}
	if token.Styled && token.Fg != "" {
		style = style.Foreground(lipgloss.Color(token.Fg))
		colored = true
	}
	if token.Styled && token.Bold {
		style = style.Bold(true)
		colored = true
	}
	if token.Styled && token.Dim {
		style = style.Faint(true)
		colored = true
	}
	if colored {
		return style.Render(plain)
	}
	return plain
}
