	m := newModel("spaces", snapshot, focus.EmptyHistory(herdr.ContinuityWitness{}), defaultSidebarLayout(), 0, 80)
	m.setSpaceCatalog([]space.Definition{{ID: "def-esc", Name: "esc", ResolvedDir: work, WorkingDir: work, Tabs: []space.DefinitionTab{{Name: "main"}}}}, nil, nil, nil)
	m.selectedID = SelectionID(KindDefinition, "def-esc")
	cmd := m.startAccept()
	done := make(chan tea.Msg, 1)
	go func() { done <- cmd() }()
	time.Sleep(30 * time.Millisecond)
	next, _ := m.Update(tea.KeyMsg{Type: tea.KeyEsc})
	m = next.(model)
	msg := <-done
	if _, ok := msg.(errorMsg); !ok && msg != nil {
		if _, ok := msg.(acceptedMsg); ok {
			t.Fatal("escape accepted create")
		}
	}
	if len(h.Created()) != 0 {
		t.Fatalf("escape created %v", h.Created())
	}
}

func TestDefinitionPickerShowsRecoveryCommands(t *testing.T) {
	def := space.Definition{ID: "def-rec", Name: "rec", ResolvedDir: "/tmp/x"}
	item := definitionItem(def, true, gitinfo.WorkspaceGit{})
	if len(item.Rows) != 1 || !strings.Contains(item.Rows[0], "(recovery needed)") {
		t.Fatalf("rows %v", item.Rows)
	}
	// The single-line row only carries the tag; the exact commands live in the preview header and the JSON listing.
	want := []string{"hseh recover def-rec --workspace <live-workspace-id>", "hseh recover def-rec --create"}
	if len(item.Recovery) != 2 || item.Recovery[0] != want[0] || item.Recovery[1] != want[1] {
		t.Fatalf("recovery commands %v", item.Recovery)
	}
	if !strings.Contains(item.PreviewText, want[0]) || !strings.Contains(item.PreviewText, want[1]) {
		t.Fatalf("preview header missing commands: %s", item.PreviewText)
	}
}
package picker

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/regutierrez/hseh/internal/focus"
	"github.com/regutierrez/hseh/internal/gitinfo"
	"github.com/regutierrez/hseh/internal/herdr"
)

func TestGitPorcelainCountsRenameConflictAndDivergence(t *testing.T) {
	payload := "# branch.oid abcdef123456\x00# branch.head topic\x00# branch.ab +2 -3\x00" +
		"2 R. N... 100644 100644 100644 abc abc R100 renamed\x00? original-name\x00" +
		"? untracked\x00u UU N... conflict\x00"
	got := gitinfo.ParseStatus(payload)
	if got.Branch != "topic" || got.Status != "+1 ?1 !1 ↑2 ↓3" {
		t.Fatalf("%+v", got)
	}
	detached := gitinfo.ParseStatus("# branch.oid abcdef123456\x00# branch.head (detached)\x00")
	if detached.Branch != "@abcdef1" || detached.Status != "" {
		t.Fatalf("%+v", detached)
	}
}

func TestGitUsesOnlyActivePaneDirectoryAndLinkedWorktree(t *testing.T) {
	root := t.TempDir()
	repo := filepath.Join(root, "main")
	worktree := filepath.Join(root, "linked")
	if err := os.Mkdir(repo, 0700); err != nil {
		t.Fatal(err)
	}
	gitFixture(t, repo, "init", "-b", "main")
	if err := os.WriteFile(filepath.Join(repo, "tracked"), []byte("file"), 0600); err != nil {
		t.Fatal(err)
	}
	gitFixture(t, repo, "add", "tracked")
	gitFixture(t, repo, "commit", "-m", "initial")
	gitFixture(t, repo, "worktree", "add", "-b", "feature", worktree)
	snapshot := herdr.SessionSnapshot{
		Workspaces: []herdr.WorkspaceRow{{WorkspaceID: "w1", Label: "Project", ActiveTabID: "w1:t1"}},
		Layouts:    []herdr.PaneLayout{{TabID: "w1:t1", FocusedPaneID: "w1:p2"}},
		Panes:      []herdr.PaneRow{{PaneID: "w1:p1", Cwd: repo}, {PaneID: "w1:p2", Cwd: repo, ForegroundCwd: worktree}},
	}
	got := LoadGit(context.Background(), snapshot, nil)
	if len(got) != 1 || got[worktree].Branch != "feature" {
		t.Fatalf("not active worktree: %+v", got)
	}
	m := newModel("spaces", snapshot, focus.EmptyHistory(herdr.ContinuityWitness{}), defaultSidebarLayout(), 0, 100)
	m.gitByDirectory = got
	if !strings.Contains(m.catalogItems()[0].SearchText, "feature") {
		t.Fatal("worktree branch missing")
	}
	m.snapshot.Panes[1].ForegroundCwd = repo
	if strings.Contains(m.catalogItems()[0].SearchText, "feature") {
		t.Fatal("old directory git result rendered after pane directory change")
	}
}

func TestGitRefreshDoesNotOverlapAndCancelsOnExit(t *testing.T) {
	m := model{view: ViewSpaces}
	defer m.io().cancelAll()
	if m.startGit() == nil || !m.gitInFlight {
		t.Fatal("git refresh not started")
	}
	if m.startGit() != nil {
		t.Fatal("overlapping git refresh")
	}
	m.quitting = true
	update(&m, gitLoadedMsg{byDirectory: map[string]gitinfo.WorkspaceGit{"old": {Branch: "stale"}}})
	if len(m.gitByDirectory) != 0 {
		t.Fatal("result applied after exit")
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if got := LoadGit(ctx, herdr.SessionSnapshot{}, nil); len(got) != 0 {
		t.Fatal(got)
	}
}

