		Workspaces:     []herdr.WorkspaceRow{{WorkspaceID: "w1", Label: "hseh", AgentStatus: "idle", ActiveTabID: "w1:t1"}},
		Layouts:        []herdr.PaneLayout{{TabID: "w1:t1", FocusedPaneID: "w1:p1"}},
