package config

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/BurntSushi/toml"
)

// DefaultPreviewPollMilliseconds is the selected visible preview poll interval.
const DefaultPreviewPollMilliseconds = 500

// DefaultWidePreviewMinColumns is the approved popup content width that shows the preview.
const DefaultWidePreviewMinColumns = 100

// Default popup geometry, matching the [[panes]] entries in herdr-plugin.toml.
var (
	DefaultPopupWidth  = PopupSize{Percent: 85}
	DefaultPopupHeight = PopupSize{Percent: 80}
)

type File struct {
	PreviewPollMs         int    `toml:"preview_poll_ms"`
	WidePreviewMinColumns int    `toml:"wide_preview_min_columns"`
	TraceFile             string `toml:"trace_file"`
	// PopupWidth and PopupHeight take a percentage string ("70%") or a cell
	// count (120), the two forms Herdr's plugin.pane.open accepts.
	PopupWidth  any `toml:"popup_width"`
	PopupHeight any `toml:"popup_height"`
}

// PopupSize is one popup dimension: exactly one of Percent or Cells is set.
type PopupSize struct {
	Percent int
	Cells   int
}

// Param is the value Herdr expects in plugin.pane.open: a "N%" string for
// percentages, a bare number for cells.
func (s PopupSize) Param() any {
	if s.Cells > 0 {
		return s.Cells
	}
	return fmt.Sprintf("%d%%", s.Percent)
}

func (s PopupSize) String() string { return fmt.Sprint(s.Param()) }

func parsePopupSize(key string, raw any) (PopupSize, error) {
	switch v := raw.(type) {
	case string:
		text := strings.TrimSpace(v)
		if !strings.HasSuffix(text, "%") {
			return PopupSize{}, fmt.Errorf("hseh config: %s %q must be a percentage like \"80%%\" or a cell count like 120", key, v)
		}
		percent, err := strconv.Atoi(strings.TrimSuffix(text, "%"))
		if err != nil || percent < 1 || percent > 100 {
			return PopupSize{}, fmt.Errorf("hseh config: %s %q must be between 1%% and 100%%", key, v)
		}
		return PopupSize{Percent: percent}, nil
	case int64:
		if v < 1 {
			return PopupSize{}, fmt.Errorf("hseh config: %s %d must be a positive cell count", key, v)
		}
		return PopupSize{Cells: int(v)}, nil
	default:
		return PopupSize{}, fmt.Errorf("hseh config: %s must be a percentage like \"80%%\" or a cell count like 120", key)
	}
}

// LoadPopupSize reads popup_width and popup_height from plugin config. Each
// dimension falls back to its default independently when unset or invalid.
func LoadPopupSize() (width, height PopupSize, errs []string) {
	width, height = DefaultPopupWidth, DefaultPopupHeight
	file, errs := LoadFile()
	if len(errs) > 0 {
		return width, height, errs
	}
	if file.PopupWidth != nil {
		if parsed, err := parsePopupSize("popup_width", file.PopupWidth); err != nil {
			errs = append(errs, err.Error())
		} else {
			width = parsed
		}
	}
	if file.PopupHeight != nil {
		if parsed, err := parsePopupSize("popup_height", file.PopupHeight); err != nil {
			errs = append(errs, err.Error())
		} else {
			height = parsed
		}
	}
	return width, height, errs
}

func LoadFile() (File, []string) {
	path := filepath.Join(ConfigDir(), "hseh.toml")
	payload, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return File{}, nil
		}
		return File{}, []string{fmt.Sprintf("hseh config: read %s: %v", path, err)}
	}
	var file File
	if err := toml.Unmarshal(payload, &file); err != nil {
		return File{}, []string{fmt.Sprintf("hseh config: parse %s: %v", path, err)}
	}
	return file, nil
}

// LoadPreviewPollInterval reads preview_poll_ms from plugin config, else 500ms.
func LoadPreviewPollInterval() (time.Duration, []string) {
	file, errs := LoadFile()
	if len(errs) > 0 {
		return time.Duration(DefaultPreviewPollMilliseconds) * time.Millisecond, errs
	}
	if file.PreviewPollMs <= 0 {
		return time.Duration(DefaultPreviewPollMilliseconds) * time.Millisecond, nil
	}
	return time.Duration(file.PreviewPollMs) * time.Millisecond, nil
}

func LoadWidePreviewMinColumns() (int, []string) {
	file, errs := LoadFile()
	if len(errs) > 0 {
		return DefaultWidePreviewMinColumns, errs
	}
	if file.WidePreviewMinColumns <= 0 {
		return DefaultWidePreviewMinColumns, nil
	}
	return file.WidePreviewMinColumns, nil
}
package config

import (
	"os"
	"path/filepath"
	"strings"
	"unicode"
)

func xdgConfigHome() string {
	if dir := os.Getenv("XDG_CONFIG_HOME"); dir != "" {
		return dir
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".config")
}

func xdgStateHome() string {
	if dir := os.Getenv("XDG_STATE_HOME"); dir != "" {
		return dir
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".local", "state")
}

// StateDir is Herdr's managed plugin state, the same directory plugin
// popup/action commands receive as HERDR_PLUGIN_STATE_DIR.
func StateDir() string {
	if dir := os.Getenv("HERDR_PLUGIN_STATE_DIR"); dir != "" {
		return dir
	}
	return filepath.Join(xdgStateHome(), "herdr", "plugins", PluginID())
}

// ConfigDir is Herdr's managed plugin config, the same directory plugin
// popup/action commands receive as HERDR_PLUGIN_CONFIG_DIR.
func ConfigDir() string {
	if dir := os.Getenv("HERDR_PLUGIN_CONFIG_DIR"); dir != "" {
		return dir
	}
	return filepath.Join(xdgConfigHome(), "herdr", "plugins", "config", PluginID())
}

func SpaceDefinitionsDir() string {
	return filepath.Join(ConfigDir(), "spaces")
}

func sessionNamespaceKey() string {
	if name := os.Getenv("HERDR_SESSION"); name != "" {
		return sanitizeSessionKey(name)
	}
	socket := SocketPath()
	if socket == "" {
		return "unknown-session"
	}
	return sanitizeSessionKey(socket)
}

func sanitizeSessionKey(raw string) string {
	var b strings.Builder
	for _, r := range raw {
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '-' || r == '.' {
			b.WriteRune(r)
			continue
		}
		b.WriteByte('_')
	}
	if b.Len() == 0 {
		return "session"
	}
	return b.String()
}

func SessionHistoryDir(stateDir string) string {
	return filepath.Join(stateDir, sessionNamespaceKey())
}

func PluginID() string {
	if id := os.Getenv("HERDR_PLUGIN_ID"); id != "" {
		return id
	}
	return "hseh"
}

func HerdrConfigPath() string {
	if path := os.Getenv("HERDR_CONFIG_PATH"); path != "" {
		return path
	}
	if dir := os.Getenv("XDG_CONFIG_HOME"); dir != "" {
		return filepath.Join(dir, "herdr", "config.toml")
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".config", "herdr", "config.toml")
}

// SocketPath is the current session socket. HERDR_SOCKET_PATH wins.
func SocketPath() string {
	if path := os.Getenv("HERDR_SOCKET_PATH"); path != "" {
		return path
	}
	return ""
}
package lockfile

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"syscall"
	"time"
)

func WithExclusive(lockPath string, fn func() error) error {
	return WithExclusiveContext(context.Background(), lockPath, fn)
}

func retryable(err error) bool {
	return errors.Is(err, syscall.EAGAIN) || errors.Is(err, syscall.EWOULDBLOCK)
}

func WithExclusiveContext(ctx context.Context, lockPath string, fn func() error) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(lockPath), 0o700); err != nil {
		return fmt.Errorf("hseh lock: mkdir %s: %w", filepath.Dir(lockPath), err)
	}
	file, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o600)
	if err != nil {
		return fmt.Errorf("hseh lock: open %s: %w", lockPath, err)
	}
	defer file.Close()
	for {
		if err := ctx.Err(); err != nil {
			return err
		}
		err := syscall.Flock(int(file.Fd()), syscall.LOCK_EX|syscall.LOCK_NB)
		if err == nil {
			break
		}
		if errors.Is(err, syscall.EINTR) {
			continue
		}
		if !retryable(err) {
			return fmt.Errorf("hseh lock: flock %s: %w", lockPath, err)
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(20 * time.Millisecond):
		}
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	return fn()
}
package trace

import (
	"fmt"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/regutierrez/hseh/internal/config"
)

// HSEH_TRACE (or trace_file in hseh.toml) names an append-only file that
// receives one line per timed event. Unset (the default) makes every hook a nil check. Lines look like:
//
//	+123.456ms socket.call dur=0.482ms method=session.snapshot bytes=16645
//
// The leading offset is relative to process start. Summaries are meant for
// sort and awk, not a dashboard.
var (
	processStart = time.Now()
	mu           sync.Mutex
	out          *os.File
	initOnce     sync.Once
)

// ProcessAge reports how long the process had existed when called, from
// /proc on Linux (10ms resolution). It exposes work done before main, such as
