	lines := strings.Split(text, "\n")
	if len(lines) <= MaxLines {
		return text
	}
	return strings.Join(lines[:MaxLines], "\n") + fmt.Sprintf("\n… %d more", len(lines)-MaxLines)
}

func firstLine(text string) string {
	if i := strings.IndexByte(text, '\n'); i >= 0 {
		return text[:i]
	}
	return text
}

