package space

import (
	"context"
	"fmt"
	"sort"
	"strings"

	"github.com/regutierrez/hseh/internal/config"
	"github.com/regutierrez/hseh/internal/focus"
	"github.com/regutierrez/hseh/internal/herdr"
	"github.com/regutierrez/hseh/internal/lockfile"
)

const (
	ActionFocus     = "focus"
	ActionAdopt     = "adopt"
	ActionCreate    = "create"
	ActionReconnect = "reconnect"
)

// OpenResult is the caller-visible outcome of create-or-focus.
type OpenResult struct {
	Action            string
	WorkspaceID       string
	SubmittedCommands int
	DefinitionID      string
	ResolvedDir       string
}

func withOpenLock(ctx context.Context, fn func() error) error {
	return lockfile.WithExclusiveContext(ctx, openLockPath(config.StateDir()), fn)
}

func workspaceGitCheckoutDir(workspace herdr.WorkspaceRow) string {
	if workspace.Worktree == nil {
		return ""
	}
	path := strings.TrimSpace(workspace.Worktree.CheckoutPath)
	if path == "" {
		return ""
	}
	canonical, err := canonicalizeDirPath(path)
	if err != nil {
		return ""
	}
	return canonical
}

func workspaceUniformPaneDir(snapshot herdr.SessionSnapshot, workspaceID string) (string, bool) {
	var dir string
	found := false
	for _, pane := range snapshot.Panes {
		if pane.WorkspaceID != workspaceID {
			continue
		}
		raw := strings.TrimSpace(pane.Cwd)
		if raw == "" {
			return "", false
		}
		canonical, err := canonicalizeDirPath(raw)
		if err != nil {
			return "", false
		}
		if !found {
			dir = canonical
			found = true
			continue
		}
		if canonical != dir {
			return "", false
		}
	}
	if !found {
		return "", false
	}
	return dir, true
}

func workspaceDirectorySignal(snapshot herdr.SessionSnapshot, workspace herdr.WorkspaceRow) (string, bool) {
	if checkout := workspaceGitCheckoutDir(workspace); checkout != "" {
		return checkout, true
	}
	return workspaceUniformPaneDir(snapshot, workspace.WorkspaceID)
}

func eligibleAdoptionWorkspaceIDs(snapshot herdr.SessionSnapshot, history focus.History, state AssociationState, definitionID, resolvedDir string) []string {
	var eligible []string
	for _, workspace := range snapshot.Workspaces {
		if workspaceAssociatedToOtherDefinition(state, workspace.WorkspaceID, definitionID, resolvedDir) {
			continue
		}
		dir, ok := workspaceDirectorySignal(snapshot, workspace)
		if !ok || dir != resolvedDir {
			continue
		}
		eligible = append(eligible, workspace.WorkspaceID)
	}
	indexOf := map[string]int{}
	for i, id := range history.Spaces {
		indexOf[id] = i
	}
	sort.SliceStable(eligible, func(i, j int) bool {
		left, leftOK := indexOf[eligible[i]]
		right, rightOK := indexOf[eligible[j]]
		if leftOK && rightOK {
			return left < right
		}
		if leftOK {
			return true
		}
		if rightOK {
			return false
		}
		return i < j
	})
	return eligible
}

func persistCreatedAssociation(stateDir string, state AssociationState, record AssociationRecord) error {
	state = upsertAssociation(state, record)
	state = removeUnresolvedAssociation(state, record.DefinitionID, record.ResolvedDir)
	return WriteAssociationFile(stateDir, state)
}

func createSpace(ctx context.Context, stateDir string, state AssociationState, def Definition) (OpenResult, error) {
	if err := preflightDirs(def); err != nil {
		return OpenResult{}, err
	}
	if err := ctx.Err(); err != nil {
		return OpenResult{}, err
	}
	workspaceID, rootTabID, rootPaneID, err := herdr.CreateWorkspace(ctx, def.ResolvedDir, def.Name, true)
	if err != nil {
		return OpenResult{}, fmt.Errorf("hseh create %s: workspace.create: %w", def.ID, err)
	}
	record := AssociationRecord{DefinitionID: def.ID, ResolvedDir: def.ResolvedDir, WorkspaceID: workspaceID}
	if err := persistCreatedAssociation(stateDir, state, record); err != nil {
		return OpenResult{Action: ActionCreate, WorkspaceID: workspaceID, DefinitionID: def.ID, ResolvedDir: def.ResolvedDir}, fmt.Errorf("hseh create %s: persist association after workspace.create %s: %w", def.ID, workspaceID, err)
	}
	submitted, err := applyLayout(ctx, def, workspaceID, rootTabID, rootPaneID)
	result := OpenResult{Action: ActionCreate, WorkspaceID: workspaceID, SubmittedCommands: submitted, DefinitionID: def.ID, ResolvedDir: def.ResolvedDir}
	if err != nil {
		return result, err
	}
	return result, nil
}

func openLocked(ctx context.Context, definitionID string) (OpenResult, error) {
	if err := ctx.Err(); err != nil {
		return OpenResult{}, err
	}
	defs, errs := LoadDefinitions(config.SpaceDefinitionsDir())
	def, ok := FindDefinitionByID(defs, definitionID)
	if !ok {
		if len(errs) > 0 {
			return OpenResult{}, fmt.Errorf("hseh open %s: not found (%s)", definitionID, strings.Join(errs, "; "))
		}
		return OpenResult{}, fmt.Errorf("hseh open: definition %s not found", definitionID)
	}
	if err := ctx.Err(); err != nil {
		return OpenResult{}, err
	}
	snapshot, witness, err := herdr.LoadSessionSnapshotContext(ctx)
	if err != nil {
		return OpenResult{}, err
	}
	stateDir := config.StateDir()
	state, err := LoadReconciledAssociationState(stateDir, witness)
	if err != nil {
		return OpenResult{}, err
	}
	history, err := focus.LoadPruned(snapshot, witness)
	if err != nil {
		return OpenResult{}, err
	}
	if err := ctx.Err(); err != nil {
		return OpenResult{}, err
	}
	if workspaceID, ok := exactLiveAssociation(state, snapshot, def.ID, def.ResolvedDir); ok {
		if err := herdr.FocusWorkspaceContext(ctx, workspaceID); err != nil {
			return OpenResult{}, err
		}
		return OpenResult{Action: ActionFocus, WorkspaceID: workspaceID, DefinitionID: def.ID, ResolvedDir: def.ResolvedDir}, nil
	}
	if identityHasUnresolvedAssociation(state, def.ID, def.ResolvedDir) {
		return OpenResult{}, recoveryNeededError(def.ID)
	}
	eligible := eligibleAdoptionWorkspaceIDs(snapshot, history, state, def.ID, def.ResolvedDir)
	if len(eligible) > 0 {
		workspaceID := eligible[0]
		state = upsertAssociation(state, AssociationRecord{
			DefinitionID: def.ID,
			ResolvedDir:  def.ResolvedDir,
			WorkspaceID:  workspaceID,
		})
		if err := WriteAssociationFile(stateDir, state); err != nil {
			return OpenResult{}, fmt.Errorf("hseh open %s: persist adoption: %w", def.ID, err)
		}
		if err := herdr.FocusWorkspaceContext(ctx, workspaceID); err != nil {
			return OpenResult{}, err
		}
		return OpenResult{Action: ActionAdopt, WorkspaceID: workspaceID, DefinitionID: def.ID, ResolvedDir: def.ResolvedDir}, nil
	}
	return createSpace(ctx, stateDir, state, def)
}

// Open focuses, adopts, or creates a definition in the current Herdr server lifetime.
func Open(ctx context.Context, definitionID string) (OpenResult, error) {
	definitionID = strings.TrimSpace(definitionID)
	if definitionID == "" {
		return OpenResult{}, fmt.Errorf("hseh open: definition id is required")
	}
	if ctx == nil {
		ctx = context.Background()
	}
	var result OpenResult
	err := withOpenLock(ctx, func() error {
		var innerErr error
		result, innerErr = openLocked(ctx, definitionID)
		return innerErr
	})
	return result, err
}
package space

import (
	"context"
	"fmt"
	"strings"

	"github.com/regutierrez/hseh/internal/config"
	"github.com/regutierrez/hseh/internal/herdr"
)

// Recover reconnects or creates an identity left unresolved after a Herdr restart.
func Recover(ctx context.Context, definitionID, workspaceID string, create bool) (OpenResult, error) {
	definitionID = strings.TrimSpace(definitionID)
	workspaceID = strings.TrimSpace(workspaceID)
	if definitionID == "" {
		return OpenResult{}, fmt.Errorf("hseh recover: definition id is required")
	}
	if create == (workspaceID != "") {
		return OpenResult{}, fmt.Errorf("hseh recover: exactly one of --workspace <live-workspace-id> or --create is required")
	}
	if ctx == nil {
		ctx = context.Background()
	}
	var result OpenResult
	err := withOpenLock(ctx, func() error {
		var innerErr error
		result, innerErr = recoverLocked(ctx, definitionID, workspaceID, create)
		return innerErr
	})
	return result, err
}

func recoverLocked(ctx context.Context, definitionID, workspaceID string, create bool) (OpenResult, error) {
	if err := ctx.Err(); err != nil {
		return OpenResult{}, err
	}
	defs, errs := LoadDefinitions(config.SpaceDefinitionsDir())
	def, ok := FindDefinitionByID(defs, definitionID)
	if !ok {
		if len(errs) > 0 {
			return OpenResult{}, fmt.Errorf("hseh recover %s: not found (%s)", definitionID, strings.Join(errs, "; "))
		}
		return OpenResult{}, fmt.Errorf("hseh recover: definition %s not found", definitionID)
	}
	if err := ctx.Err(); err != nil {
		return OpenResult{}, err
	}
	snapshot, witness, err := herdr.LoadSessionSnapshotContext(ctx)
	if err != nil {
		return OpenResult{}, err
	}
	stateDir := config.StateDir()
	state, err := LoadReconciledAssociationState(stateDir, witness)
	if err != nil {
		return OpenResult{}, err
	}
	if err := ctx.Err(); err != nil {
		return OpenResult{}, err
	}
	if liveID, exact := exactLiveAssociation(state, snapshot, def.ID, def.ResolvedDir); exact {
		if !create && workspaceID != liveID {
			return OpenResult{}, fmt.Errorf("hseh recover: definition %s is already associated with %s", def.ID, liveID)
		}
		if err := herdr.FocusWorkspaceContext(ctx, liveID); err != nil {
			return OpenResult{}, err
		}
		return OpenResult{Action: ActionFocus, WorkspaceID: liveID, DefinitionID: def.ID, ResolvedDir: def.ResolvedDir}, nil
	}
	if !identityHasUnresolvedAssociation(state, def.ID, def.ResolvedDir) {
		return OpenResult{}, fmt.Errorf("hseh recover: definition %s does not need recovery", def.ID)
	}
	if create {
		return createSpace(ctx, stateDir, state, def)
	}
	if !liveWorkspaceIDs(snapshot)[workspaceID] {
		return OpenResult{}, fmt.Errorf("hseh recover: workspace %s is not live", workspaceID)
	}
	if workspaceAssociatedToOtherDefinition(state, workspaceID, def.ID, def.ResolvedDir) {
		return OpenResult{}, fmt.Errorf("hseh recover: workspace %s is associated with another definition", workspaceID)
	}
	if err := ctx.Err(); err != nil {
		return OpenResult{}, err
	}
	record := AssociationRecord{DefinitionID: def.ID, ResolvedDir: def.ResolvedDir, WorkspaceID: workspaceID}
	if err := persistCreatedAssociation(stateDir, state, record); err != nil {
		return OpenResult{}, fmt.Errorf("hseh recover %s: persist reconnection: %w", def.ID, err)
	}
	if err := herdr.FocusWorkspaceContext(ctx, workspaceID); err != nil {
		return OpenResult{}, err
	}
	return OpenResult{Action: ActionReconnect, WorkspaceID: workspaceID, DefinitionID: def.ID, ResolvedDir: def.ResolvedDir}, nil
}
package space

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"github.com/regutierrez/hseh/internal/config"
	"github.com/regutierrez/hseh/internal/herdr"
)

// AssociationRecord is one definition-id + resolved-dir to live workspace link.
type AssociationRecord struct {
	DefinitionID string `json:"definition_id"`
	ResolvedDir  string `json:"resolved_dir"`
	WorkspaceID  string `json:"workspace_id"`
}

// AssociationState is session-scoped association provenance for one proven server.
// Unresolved holds identities from earlier server generations that need explicit recovery.
type AssociationState struct {
	Witness    herdr.ContinuityWitness `json:"witness"`
	Records    []AssociationRecord     `json:"records"`
	Unresolved []AssociationRecord     `json:"unresolved"`
}

func associationStatePath(stateDir string) string {
	return filepath.Join(config.SessionHistoryDir(stateDir), "associations.json")
}

func openLockPath(stateDir string) string {
	return filepath.Join(config.SessionHistoryDir(stateDir), "space-open.lock")
}

func AssociationIdentityKey(definitionID, resolvedDir string) string {
	return definitionID + "\n" + resolvedDir
}

func LoadAssociationFile(stateDir string) (AssociationState, error) {
	payload, err := os.ReadFile(associationStatePath(stateDir))
	if err != nil {
		if os.IsNotExist(err) {
			return AssociationState{}, nil
		}
		return AssociationState{}, fmt.Errorf("hseh association: read: %w", err)
	}
	var state AssociationState
	if err := json.Unmarshal(payload, &state); err != nil {
		return AssociationState{}, fmt.Errorf("hseh association: corrupt state: %w", err)
	}
	if state.Records == nil {
		state.Records = []AssociationRecord{}
	}
	if state.Unresolved == nil {
		state.Unresolved = []AssociationRecord{}
	}
	return state, nil
}

func WriteAssociationFile(stateDir string, state AssociationState) error {
	dir := config.SessionHistoryDir(stateDir)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return fmt.Errorf("hseh association: mkdir: %w", err)
	}
	payload, err := json.Marshal(state)
	if err != nil {
		return fmt.Errorf("hseh association: encode: %w", err)
	}
	temporaryPath := filepath.Join(dir, fmt.Sprintf("associations.%d.tmp", os.Getpid()))
	if err := os.WriteFile(temporaryPath, append(payload, '\n'), 0o600); err != nil {
		return fmt.Errorf("hseh association: write: %w", err)
	}
	if err := os.Rename(temporaryPath, associationStatePath(stateDir)); err != nil {
		_ = os.Remove(temporaryPath)
		return fmt.Errorf("hseh association: rename: %w", err)
	}
	return nil
}

func associationWitnessEmpty(witness herdr.ContinuityWitness) bool {
	return witness.PeerPID == 0 && witness.PeerStartTime == ""
}

func associationWitnessMismatch(state AssociationState, live herdr.ContinuityWitness) bool {
	if associationWitnessEmpty(state.Witness) && len(state.Records) == 0 {
		return false
	}
	return !herdr.SameContinuityWitness(state.Witness, live)
}

func appendUnresolvedAssociation(state AssociationState, record AssociationRecord) AssociationState {
	key := AssociationIdentityKey(record.DefinitionID, record.ResolvedDir)
	for _, existing := range state.Unresolved {
		if AssociationIdentityKey(existing.DefinitionID, existing.ResolvedDir) == key {
			return state
		}
	}
	state.Unresolved = append(state.Unresolved, record)
	return state
}

func removeUnresolvedAssociation(state AssociationState, definitionID, resolvedDir string) AssociationState {
	key := AssociationIdentityKey(definitionID, resolvedDir)
	kept := []AssociationRecord{}
	for _, record := range state.Unresolved {
		if AssociationIdentityKey(record.DefinitionID, record.ResolvedDir) == key {
			continue
		}
		kept = append(kept, record)
	}
	state.Unresolved = kept
	return state
}

func identityHasUnresolvedAssociation(state AssociationState, definitionID, resolvedDir string) bool {
	key := AssociationIdentityKey(definitionID, resolvedDir)
	for _, record := range state.Unresolved {
		if AssociationIdentityKey(record.DefinitionID, record.ResolvedDir) == key {
			return true
		}
	}
	return false
}

// ReconcileAssociationState folds mismatched current records into unresolved in memory.
// It does not write. Picker reads must not persist a witness reset.
func ReconcileAssociationState(state AssociationState, live herdr.ContinuityWitness) AssociationState {
	if state.Records == nil {
		state.Records = []AssociationRecord{}
	}
	if state.Unresolved == nil {
		state.Unresolved = []AssociationRecord{}
	}
	if !associationWitnessMismatch(state, live) {
		state.Witness = live
		return state
	}
	for _, record := range state.Records {
		state = appendUnresolvedAssociation(state, record)
	}
	state.Records = []AssociationRecord{}
	state.Witness = live
	return state
}

func LoadReconciledAssociationState(stateDir string, live herdr.ContinuityWitness) (AssociationState, error) {
	state, err := LoadAssociationFile(stateDir)
	if err != nil {
		return AssociationState{}, err
	}
	return ReconcileAssociationState(state, live), nil
}

func RecoveryHintLines(definitionID string) []string {
	return []string{
		"recovery needed",
		"hseh recover " + definitionID + " --workspace <live-workspace-id>",
		"hseh recover " + definitionID + " --create",
	}
}

func recoveryNeededError(definitionID string) error {
	return fmt.Errorf("hseh open: definition %s needs recovery after Herdr restart; use `hseh recover %s --workspace <live-workspace-id>` or `hseh recover %s --create`", definitionID, definitionID, definitionID)
}

func upsertAssociation(state AssociationState, record AssociationRecord) AssociationState {
	replaced := false
	for i, existing := range state.Records {
		if existing.DefinitionID == record.DefinitionID && existing.ResolvedDir == record.ResolvedDir {
			state.Records[i] = record
			replaced = true
			break
		}
	}
	if !replaced {
		state.Records = append(state.Records, record)
	}
	return state
}

func liveWorkspaceIDs(snapshot herdr.SessionSnapshot) map[string]bool {
	live := map[string]bool{}
	for _, workspace := range snapshot.Workspaces {
		if workspace.WorkspaceID != "" {
			live[workspace.WorkspaceID] = true
		}
	}
	return live
}

func workspaceAssociatedToOtherDefinition(state AssociationState, workspaceID, definitionID, resolvedDir string) bool {
	for _, record := range state.Records {
		if record.WorkspaceID != workspaceID {
			continue
		}
		if record.DefinitionID == definitionID && record.ResolvedDir == resolvedDir {
			continue
		}
		return true
	}
	return false
}

func exactLiveAssociation(state AssociationState, snapshot herdr.SessionSnapshot, definitionID, resolvedDir string) (string, bool) {
	live := liveWorkspaceIDs(snapshot)
	for _, record := range state.Records {
		if record.DefinitionID == definitionID && record.ResolvedDir == resolvedDir && live[record.WorkspaceID] {
			return record.WorkspaceID, true
		}
	}
	return "", false
}

func AssociatedLiveDefinitionKeys(state AssociationState, snapshot herdr.SessionSnapshot) map[string]bool {
	live := liveWorkspaceIDs(snapshot)
	keys := map[string]bool{}
	for _, record := range state.Records {
		if live[record.WorkspaceID] {
			keys[AssociationIdentityKey(record.DefinitionID, record.ResolvedDir)] = true
		}
	}
	return keys
}
package space

import (
	"context"
	"fmt"
	"os"
	"strings"

	"github.com/regutierrez/hseh/internal/herdr"
)

func preflightDirs(def Definition) error {
	info, err := os.Stat(def.ResolvedDir)
	if err != nil || !info.IsDir() {
		return fmt.Errorf("hseh create %s: working directory does not exist: %s", def.ID, def.ResolvedDir)
	}
	if err := checkTabDirs(def.ResolvedDir, def.Tabs); err != nil {
		return fmt.Errorf("hseh create %s: %w", def.ID, err)
	}
	return nil
}

type pendingPaneCommand struct {
	paneID  string
	command string
}

func applyLayout(ctx context.Context, def Definition, workspaceID, rootTabID, rootPaneID string) (int, error) {
	dirs, err := resolvePaneDirs(def.ResolvedDir, def.Tabs)
	if err != nil {
		return 0, fmt.Errorf("hseh create %s: %w", def.ID, err)
	}
	var runs []pendingPaneCommand
	submitted := 0
	for i, tab := range def.Tabs {
		tabRoot := rootPaneID
		if i == 0 {
			if dir := dirs[i][0]; dir != "" && dir != def.ResolvedDir {
				_, tabRoot, err = herdr.CreateTab(ctx, workspaceID, tab.Name, dir, true)
				if err != nil {
					return submitted, fmt.Errorf("hseh create %s: tab.create %q: %w", def.ID, tab.Name, err)
				}
				if err = herdr.CloseTab(ctx, rootTabID); err != nil {
					return submitted, fmt.Errorf("hseh create %s: close replaced root tab: %w", def.ID, err)
				}
			} else if err = herdr.RenameTab(ctx, rootTabID, tab.Name); err != nil {
				return submitted, fmt.Errorf("hseh create %s: tab.rename %q: %w", def.ID, tab.Name, err)
			}
		} else {
			_, tabRoot, err = herdr.CreateTab(ctx, workspaceID, tab.Name, dirs[i][0], false)
			if err != nil {
				return submitted, fmt.Errorf("hseh create %s: tab.create %q: %w", def.ID, tab.Name, err)
			}
		}
		prev := tabRoot
		for j, pane := range tab.effectivePanes() {
			paneID := tabRoot
			if j > 0 {
				paneID, err = herdr.SplitPane(ctx, prev, pane.Split, pane.splitRatio(), dirs[i][j], false)
				if err != nil {
					return submitted, fmt.Errorf("hseh create %s: pane.split tab %q pane %d: %w", def.ID, tab.Name, j+1, err)
				}
			}
			if lbl := strings.TrimSpace(pane.Label); lbl != "" {
				if err := herdr.RenamePane(ctx, paneID, lbl); err != nil {
					return submitted, fmt.Errorf("hseh create %s: pane.rename tab %q pane %d: %w", def.ID, tab.Name, j+1, err)
				}
			}
			if strings.TrimSpace(pane.Command) != "" {
				runs = append(runs, pendingPaneCommand{paneID: paneID, command: pane.Command})
			}
			prev = paneID
		}
	}
	for _, run := range runs {
		if err := herdr.SubmitPaneCommand(ctx, run.paneID, run.command); err != nil {
			return submitted, fmt.Errorf("hseh create %s: pane.send_input %s: %w", def.ID, run.paneID, err)
		}
		submitted++
	}
	return submitted, nil
}

