		"HERDR_PLUGIN_STATE_DIR="+stateDir,
		"HERDR_PLUGIN_CONFIG_DIR="+configDir,
		"HERDR_SESSION=hseh-test",
		"HERDR_PLUGIN_ID=hseh",
