func (r *burstPreviewReader) read(ctx context.Context, paneID string) (string, error) {
	timer := time.NewTimer(r.delay)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		r.cancelled.Add(1)
		return "", ctx.Err()
	case <-timer.C:
		r.completed.Add(1)
		return "frame:" + paneID, nil
	}
